-- 투데이오늘: 4차산업·사회·기획특집·포토뉴스 시작 기사 34건 — 승인대기, 정부·공공기관 보도자료를 바탕으로 새로 쓴 기사
-- Supabase SQL 에디터에서 실행 (newstoday-sections.sql 다음). 여러 번 실행해도 된다 (같은 제목 기사는 건너뛴다)
--   · 사진: 저장소의 /sites/newstoday/photos/ 에 있는 이미지를 쓴다 (배포가 끝난 뒤에 사진이 보인다)
--   · 작성: 투데이오늘 관리자 계정(없으면 편집장 → 총관리자), 기자명 '편집국'
--   · 기사마다 '확인할 점'·원문 주소·사진 이용 조건을 AI 메모(편집 메모)에 남겼다

with ctx as (
  select o.id as outlet_id, o.name as outlet_name,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'admin' order by p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'editor' order by p.created_at limit 1),
           (select p.id from profiles p where (to_jsonb(p) ->> 'is_super') = 'true' order by p.created_at limit 1),
           (select p.id from profiles p where p.role = 'admin' order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = '투데이오늘'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags, press_release_id)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[' || ctx.outlet_name || '=편집국]'),
       v.excerpt, v.thumb, v.status, v.published_at, v.tags,
       null
from ctx
cross join (values
  ('ai', 'AI가 폐기물 식별·배출 안내…서울 은평구서 ''가져가'' 앱 실증 시작', '<p>@@BYLINE@@&nbsp;과학기술정보통신부와 기후에너지환경부는 12일 보도자료에서 인공지능(AI)으로 폐기물을 식별하고 배출 방법을 안내하는 모바일 앱 ''가져가''의 실증을 13일부터 서울 은평구 주민을 대상으로 시작한다고 밝혔다. 앱의 정식 이름은 ''내 손안의 인공지능 폐기물 처리 도우미, 가져가''다.</p><p>이 앱은 과기정통부의 공공 인공지능 전환 사업(AX 프로젝트)의 하나로 개발 중이다. 두 부처는 지역마다 폐기물 배출 규정과 절차가 달라 주민이 겪는 불편을 줄이고, 분리배출 안내부터 대형폐기물 수수료 결제까지 한 번에 처리할 수 있게 하는 것을 목표로 한다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-ai-1.webp" alt="국내 지자체의 재활용품 분리배출함(자료사진, 부산 해운대구 촬영). 사진: ProjectManhattan/위키미디어 공용 (CC BY-SA 3.0)"><p><em>▲ 국내 지자체의 재활용품 분리배출함(자료사진, 부산 해운대구 촬영). 사진: ProjectManhattan/위키미디어 공용 (CC BY-SA 3.0)</em></p><p>주요 기능은 세 가지다. 스마트폰 카메라로 폐기물을 촬영하면 AI가 품목을 자동으로 인식·분류하고, 사용자 위치정보(GPS)와 연동해 해당 지역의 배출 요일과 수수료, 분리배출 방법을 안내한다. 대형 가구와 가전제품은 배출 신고부터 수수료 결제까지 앱 안에서 처리할 수 있다.</p><p>정부는 은평구 실증에서 AI 모델의 식별 정확도와 서비스의 편의성·안정성을 집중적으로 검증할 계획이다. 실증 과정에서 모은 사용자 의견과 운용 데이터를 바탕으로 서비스 완성도를 높이고, 지방정부 수요와 유지관리 여건 등을 고려해 단계적으로 확대한다는 방침이다.</p><p>사업은 과기정통부 ''공공AX프로젝트'' 20개 과제 가운데 국민체감 분야로 추진된다. 전담기관은 정보통신산업진흥원(NIPA), 협력기관은 한국환경공단이며 교림소프트 컨소시엄이 수행한다. 수행 기간은 2025년 10월부터 2026년 12월까지, 사업비는 33억 8천만 원(국비 25억 5천만 원)이다.</p><p>과기정통부 정보통신정책관은 "앞으로도 과기정통부는 인공지능의 혜택을 국민이 실질적으로 체감할 수 있도록 관계부처와 긴밀히 협력하여 다양한 인공지능 서비스를 준비해 나가겠다"고 밝혔다. 기후에너지환경부 자원순환국장은 AI 기반 자원순환 행정을 적극 추진하겠다고 말했다. 은평구 주민은 13일부터 구글 플레이스토어 또는 애플 앱스토어에서 ''가져가'' 앱을 내려받아 사용해 볼 수 있다.</p>', '과기정통부와 기후에너지환경부는 12일 인공지능으로 폐기물 품목을 식별하고 지역별 배출 방법을 안내하는 앱 ''가져가''의 시범 서비스를 서울 은평구 주민 대상으로 13일 시작한다고 밝혔다.', '/sites/newstoday/photos/ntd-ai-1.webp', '2026-10-13T09:05:00+09:00'::timestamptz, array['인공지능','폐기물','분리배출','은평구','과기정통부']::text[], 'in_review'),
  ('ai', 'AI 학습용 데이터 연계 의무화…AI기본법·데이터산업법 개정안 국무회의 통과', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 13일 「인공지능 기본법」과 「데이터 산업법」 개정안이 이날 국무회의를 통과했다고 밝혔다. 정부 사업으로 구축·산출된 인공지능(AI) 학습용 데이터의 확보와 제공을 넓히고, 공공·민간 데이터의 소재 정보를 통합 제공하는 제도적 기반을 마련하는 내용이다.</p><p>과기정통부는 대학·중소기업이 자체 확보하기 어려운 AI 학습용 데이터를 대규모로 구축해 개방하는 ''인공지능 거점(AI 허브)''을 2018년부터 운영하고 있다. 정부 사업으로 구축한 학습용 데이터는 2025년 말 기준 945종이다. 개정된 인공지능 기본법은 정부 사업 등을 수행하며 구축·산출한 AI 학습용 데이터를 AI 허브에 연계·제공하도록 의무화했다.</p><img src="/sites/newstoday/photos/ntd-ai-2.webp" alt="정부세종청사 전경(자료사진). 사진: Minseong Kim/위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 정부세종청사 전경(자료사진). 사진: Minseong Kim/위키미디어 공용 (CC BY-SA 4.0)</em></p><p>다만 사업 수행자 등이 영업비밀 보호, 개인정보·저작권 침해, 국가 안전보장 등 대통령령으로 정하는 사유에 해당한다고 판단하면 데이터를 연계하거나 제공하지 않을 수 있도록 했다. 과기정통부 장관과 관계 중앙행정기관의 장이 연계·제공에 필요한 행정적·재정적·기술적 지원을 할 수 있고, 데이터 품질관리에 필요한 조치도 하도록 규정했다.</p><p>데이터 산업법 개정안은 공공·민간 데이터 플랫폼을 연계해 데이터 소재 정보를 제공하는 ''원-윈도우(data1window.kr)''와 관련된다. 과기정통부는 이 서비스를 2025년부터 운영 중이며, 2026년 8월 기준 88개 플랫폼이 연계돼 있다. 개정안은 과기정통부 장관이 공공기관과 민간법인 등에 연계 협력을 요청할 수 있게 하고, 공공기관은 특별한 사유가 없으면 이에 따르도록 했다.</p><p>연계에 필요한 기술적·재정적 지원 근거도 마련했다. 두 개정안은 공포 후 6개월 뒤인 2027년 4월 시행될 예정이며, 과기정통부는 하위법령 정비를 서두르겠다고 밝혔다. 과기정통부 인공지능정책실장은 "이번 법 개정을 통해 국가 인공지능 데이터 활용 기반을 강화하고, 인공지능 산업 발전을 뒷받침하겠다"고 밝혔다.</p>', '과기정통부는 정부 사업으로 구축된 AI 학습용 데이터를 ''AI 허브''에 연계·제공하도록 하는 인공지능 기본법 개정안과 데이터 산업법 개정안이 13일 국무회의를 통과했다고 밝혔다. 2027년 4월 시행 예정이다.', '/sites/newstoday/photos/ntd-ai-2.webp', '2026-10-13T14:20:00+09:00'::timestamptz, array['인공지능기본법','데이터산업법','AI허브','국무회의','과기정통부']::text[], 'in_review'),
  ('ai', '과기정통부·세계은행, 서울서 국제 AI·디지털 정상회의…60여 개국 참석', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 19일 보도자료에서 세계은행과 함께 10월 19일부터 22일까지 서울 그랜드하얏트에서 ''국제 인공지능·디지털 정상회의(Global AI·Digital Summit, GADS)''를 개최한다고 밝혔다. 세계은행이 미국 밖에서 여는 첫 인공지능(AI)·디지털 정상회의다.</p><p>세계은행은 189개 회원국을 둔 국제기구다. 과기정통부는 세계은행의 개발 협력 경험과 국제 네트워크를 활용해 한국의 AI·디지털 기술과 정책 경험을 공유하고, 개발도상국과의 협력 기회를 넓히려고 행사를 공동 개최했다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-ai-3.webp" alt="행사가 열린 서울 그랜드하얏트 호텔 외관(자료사진). 사진: Matt Kieffer/위키미디어 공용 (CC BY-SA 2.0)"><p><em>▲ 행사가 열린 서울 그랜드하얏트 호텔 외관(자료사진). 사진: Matt Kieffer/위키미디어 공용 (CC BY-SA 2.0)</em></p><p>첫날인 19일에는 AI·디지털 장관회의가 열렸다. 배경훈 부총리 겸 과기정통부 장관과 세계은행 부총재가 공동의장을 맡았고, 60여 개국 장·차관급 대표가 참석했다. 참가국은 ''구상에서 실행으로(From Ambition to Action)''를 주제로 디지털 포용과 접근성 확대, AI를 활용한 공공서비스 혁신, 혁신적인 AI·디지털 생태계 조성을 논의하고 의장 성명문을 발표했다.</p><p>20~21일에는 각국 정부와 국제기구, 산업계, 학계 전문가가 참여하는 정책 토론회와 국내외 기업의 기술 전시가 이어진다. 20일에는 경제부총리가 개회사를 할 예정이며, 21일에는 행정안전부 차관과 과기정통부 인공지능정책실장이 한국의 정책 경험을 공유할 예정이다.</p><p>마지막 날인 22일에는 해외 참가자들이 한국의 AI·디지털 기술 활용 현장을 살펴보는 현장 견학이 진행된다. 한국수자원공사와 분당서울대학교병원 등을 방문할 예정이다. 류제명 과기정통부 2차관은 19일 고위급 교류 분과와 만찬에 참석해 ''모두의 인공지능'' 등 한국의 주요 AI 정책을 소개할 계획이다.</p><p>과기정통부는 2005년부터 디지털 장관회의를 개최해 왔으며, 지난해에는 아시아태평양경제협력체(APEC) 계기에 21개 회원경제가 참석한 AI·디지털 장관회의를 열었다. 배경훈 부총리는 "책임 있는 인공지능 활용을 통해 그 혜택이 인류 전체에 고루 돌아갈 수 있도록 국제사회와 적극 협력하겠다"고 밝혔다.</p>', '과기정통부는 19일 세계은행과 함께 19~22일 서울 그랜드하얏트에서 국제 인공지능·디지털 정상회의를 개최한다고 밝혔다. 19일 장관회의에는 60여 개국 장·차관급 대표가 참석했다.', '/sites/newstoday/photos/ntd-ai-3.webp', '2026-10-20T09:10:00+09:00'::timestamptz, array['인공지능','세계은행','디지털','국제협력','과기정통부']::text[], 'in_review'),
  ('ai', '과기정통부, 13~14일 코엑스서 ''피지컬 AI Tech Week'' 개최', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 12일 보도자료에서 10월 13일부터 14일까지 이틀간 서울 코엑스에서 「물리적 인공지능 기술 주간(피지컬 AI Tech Week)」을 개최한다고 밝혔다. 과기정통부가 주최하고 물리적 인공지능 협력체(피지컬 AI 얼라이언스)와 정보통신산업진흥원이 주관하는 종합행사다.</p><p>행사는 정부 사업 설명회와 교류 행사, 해외 기술 강연, 기술 전시·시연, 이야기 마당(토크콘서트)으로 구성된다. 협력체 참여 기업·기관 400여 개사를 비롯해 벤처캐피탈과 관계기관 관계자 등 500명 이상이 참여할 예정이다.</p><img src="/sites/newstoday/photos/ntd-ai-4.webp" alt="행사가 열린 서울 코엑스 입구(자료사진). 사진: 위키미디어 공용 &#x27;Seoul-COEX.jpg&#x27; (퍼블릭 도메인)"><p><em>▲ 행사가 열린 서울 코엑스 입구(자료사진). 사진: 위키미디어 공용 ''Seoul-COEX.jpg'' (퍼블릭 도메인)</em></p><p>첫날인 13일은 ''협력체의 날''로 2027년도 정부의 피지컬 AI 사업 방향을 공유한다. 오전에는 국내외 기업 관계자들이 특별강연을 하고, 과기정통부·중소벤처기업부·농림축산식품부·해양수산부 등이 참여하는 ''2027년 범부처 피지컬 AI 사업설명회''가 열린다. 제조·물류·농업·항만 분야 주요 사업과 국민성장펀드가 소개되며, 오후에는 3개 분과별 교류 행사가 이어진다.</p><p>둘째 날인 14일은 ''행동하는 두뇌, Intelligence into Action''을 구호로 한 ''기술의 날''이다. 오전에는 국내외 전문가 3명이 인공지능 추론 기반, 신체 지능 구조, 로봇 기초 모형 등을 주제로 기조강연을 한다. 오후에는 두 개 기술 분과에서 AI 팩토리, 디지털트윈, 피지컬 AI 표준화, 데이터·제어, 로봇 협업지능 등 핵심기술과 산업 현장 적용 사례를 다룬다.</p><p>14일 오후에는 일반 시민의 눈높이에 맞춘 ''피지컬 AI 이야기 마당''도 마련된다. ''대중이 묻고 연구진이 답하다''를 주제로 학생·기업인·연구자 70여 명이 참여해 로봇과 피지컬 AI의 차이, 피지컬 AI가 가져올 산업과 일상의 변화 등을 두고 질문하고 의견을 나눈다.</p><p>행사 기간 상설 운영되는 기술 전시에는 KT, LG CNS 등 기업과 연구기관이 참여한다. 데이터센터·엣지용 AI 추론 신경망 처리장치(NPU), 제조 AI 기반 가상공장 제어, 지능형 로봇과 인간형 로봇(휴머노이드), 마이크로 엣지 서버 등을 실물·영상·시연으로 선보인다. 과기정통부 관계자는 이번 행사가 피지컬 AI의 기술과 산업 동향을 공유하고 정부와 기업·연구기관 사이에 새로운 협력 기회를 만드는 자리가 되기를 기대한다고 밝혔다.</p>', '과기정통부는 12일 물리적 인공지능 협력체와 정보통신산업진흥원이 주관하는 종합행사 ''피지컬 AI Tech Week''를 13~14일 서울 코엑스에서 개최한다고 밝혔다. 500명 이상이 참여할 예정이다.', '/sites/newstoday/photos/ntd-ai-4.webp', '2026-10-12T13:00:00+09:00'::timestamptz, array['피지컬AI','인공지능','로봇','코엑스','과기정통부']::text[], 'in_review'),
  ('ai', 'KAIST·UNIST 등, 2차원 반도체 결정 생성 위치 제어…네이처 게재', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 8일 보도자료에서 한국과학기술원(KAIST), 울산과학기술원(UNIST), 한양대학교, 티디에스이노베이션(TDS Innovation)이 참여한 공동연구팀이 2차원 반도체 결정이 생기는 위치를 정하고 그곳에서 하나의 결정만 자라도록 제어하는 기술을 개발했다고 밝혔다. 차세대 적층형 인공지능(AI) 반도체 구현의 기반이 될 것으로 기대된다는 설명이다.</p><p>연구 결과는 국제학술지 네이처(Nature)에 10월 8일 게재됐다. 과기정통부의 개인기초연구 사업과 나노소재기술개발 사업 지원으로 수행됐다. 연구에는 KAIST 강기범 교수, UNIST 김병조 교수, 한양대 김우희 교수 등이 참여했다.</p><img src="/sites/newstoday/photos/ntd-ai-5.webp" alt="KAIST·UNIST 공동연구팀의 2차원 반도체 연구 성과를 담은 그림(일부 잘라 사용). ⓒ 과학기술정보통신부 보도자료 첨부 (공공누리 제1유형)"><p><em>▲ KAIST·UNIST 공동연구팀의 2차원 반도체 연구 성과를 담은 그림(일부 잘라 사용). ⓒ 과학기술정보통신부 보도자료 첨부 (공공누리 제1유형)</em></p><p>원자층 두께의 2차원 반도체는 기존 연산 회로 위에 반도체를 더 쌓아 올려 칩 성능을 높이고 전력 소모를 줄일 수 있는 차세대 소재로 꼽힌다. 다만 여러 곳에서 제각각 자란 결정이 만나면 원자 배열이 어긋난 경계가 생겨 전자 이동을 방해하고 반도체 품질이 떨어진다. 미리 정한 영역에서만 반도체를 키우는 기존 ''선택성장'' 기술도 영역 안에서 결정핵이 생기는 위치와 개수는 확률에 맡겨져 있었다.</p><p>연구팀은 성장 영역을 둘러싼 산화하프늄 등 산화물 장벽에서 나오는 산소 성분이 이황화몰리브덴의 결정핵 형성을 억제한다는 점에 주목했다. 이 억제 작용은 장벽에 가까운 가장자리에서 강하고 중앙에서는 약한데, 이 차이를 이용해 성장 영역 중앙에서 하나의 결정핵만 생기도록 유도했다. 이 결정이 옆으로 자라면 결정 경계 없이 하나로 이어지는 단결정이 된다.</p><p>연구팀은 400개 실험 패턴 가운데 99% 이상에서 중앙에 이황화몰리브덴 단결정을 하나씩 형성하는 데 성공했다고 밝혔다. 과기정통부는 성장 영역을 정하는 데서 나아가 성장이 시작되는 위치까지 설계할 수 있게 됐다는 점에 의미가 있다고 설명했다.</p><p>과기정통부는 이 기술이 회로 설계에 맞춰 필요한 위치에 고품질 반도체를 직접 키우는 제조 기술로 발전하면 차세대 소자를 여러 층으로 쌓는 적층 공정의 기반이 될 것으로 기대된다고 밝혔다. 연산 처리부와 메모리를 수직으로 가깝게 배치하면 데이터 이동에 드는 시간과 에너지를 줄여 데이터센터 전력 부담을 덜고 AI 서비스 응답 시간을 단축하는 데 도움이 될 것이라는 설명도 덧붙였다.</p><p>KAIST 강기범 교수는 2차원 반도체 성장 과정에서 결정이 어디에서 시작될지를 정밀하게 제어할 수 있는 새로운 가능성을 확인했다는 점에서 의미가 있다고 밝혔다. 과기정통부 연구개발정책실장은 연구자들의 창의적인 연구를 이어가도록 지원을 아끼지 않겠다고 말했다.</p>', '과기정통부는 8일 KAIST·UNIST·한양대 등 공동연구팀이 2차원 반도체 결정이 생기는 위치를 정하고 하나의 결정만 자라게 하는 기술을 개발해 학술지 네이처에 게재했다고 밝혔다.', '/sites/newstoday/photos/ntd-ai-5.webp', '2026-10-08T09:15:00+09:00'::timestamptz, array['반도체','2차원반도체','인공지능반도체','KAIST','네이처']::text[], 'in_review'),
  ('industry4-general', 'IBS, 원자 치환으로 한 박막에 반도체·절연체·준금속 구현…사이언스 게재', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 16일 보도자료에서 기초과학연구원(IBS) 반데르발스 양자 물질 연구단 조문호 단장 연구팀이 2차원 반도체를 이루는 원자를 선택적으로 바꿔 하나의 박막에 반도체·절연체·준금속 영역을 원하는 층과 위치에 구현하는 ''모듈형 트랜지스터 제작 기술''을 개발했다고 밝혔다. 연구 결과는 국제학술지 사이언스(Science)에 16일 오전 3시(한국표준시) 게재됐다.</p><p>원자층 두께에서도 전류를 제어할 수 있는 2차원 반도체는 실리콘 반도체의 미세화 한계를 넘을 차세대 소재로 주목받는다. 그러나 2차원 반도체는 표면이 다른 물질과 화학적으로 잘 결합하지 않아 절연막을 균일하게 입히기 어렵고, 금속 전극을 직접 붙이면 접촉면이 손상되거나 전기 저항이 커질 수 있다. 서로 다른 얇은 물질을 한 장씩 옮겨 쌓는 방법은 공정이 복잡해 넓은 면적이나 대량 생산에 적용하기 어렵다.</p><img src="/sites/newstoday/photos/ntd-industry4-general-1.webp" alt="기초과학연구원(IBS) 반데르발스 양자 물질 연구단 핵심 연구진 ⓒ 과학기술정보통신부·IBS (공공누리 제1유형)"><p><em>▲ 기초과학연구원(IBS) 반데르발스 양자 물질 연구단 핵심 연구진 ⓒ 과학기술정보통신부·IBS (공공누리 제1유형)</em></p><p>연구팀은 물질을 쌓는 대신 2차원 반도체를 이루는 원자를 바꿔 필요한 물질을 원하는 위치에 직접 만드는 방식을 택했다. p형 반도체인 이셀레늄화텅스텐의 셀레늄 원자를 산소, 황, 텔루륨으로 선택적으로 치환해 각각 절연체인 산화텅스텐, n형 반도체인 이황화텅스텐, 준금속인 이텔루륨화텅스텐으로 바꿨다. 반응 온도와 반응 기체 압력을 조절해 약 0.7나노미터 두께의 원자층 단위로 변환했으며, 반도체 공정용 마스크로 평면상의 원하는 위치만 바꾸는 데도 성공했다.</p><p>준금속 접합층을 적용하자 금속 전극에서 반도체로 전하가 이동할 때 넘어야 하는 에너지 장벽이 35.5밀리전자볼트로 낮아졌다. 금속 전극을 직접 붙인 경우의 약 3분의 1 수준이다. 전류를 10배로 바꾸는 데 필요한 게이트 전압 변화량은 61.3밀리볼트로 상온 이론적 최솟값인 약 60밀리볼트에 근접했고, 켜짐·꺼짐 전류 비율은 1,000만 배 이상으로 나타났다.</p><p>산화텅스텐 절연막의 등가 산화막 두께는 1나노미터 미만으로, 국제 반도체 로드맵이 제시한 초미세 소자의 핵심 성능 목표 수준을 달성했다. 연구팀은 p형과 n형 트랜지스터를 수직으로 쌓아 상보형 인버터도 만들었으며, 1볼트의 낮은 전압에서도 신호가 반전돼 적층형 집적회로로 확장할 가능성을 보였다고 밝혔다.</p><p>연구진은 이 기술을 다양한 2차원 반도체 소재에 적용하고 웨이퍼 크기의 대면적 공정으로 발전시키는 한편, 3차원 적층형 집적회로 등으로의 응용 가능성을 탐색할 계획이다. 이번 연구는 과기정통부의 IBS 기초과학연구단 지원 사업으로 수행됐다.</p><p>조문호 IBS 단장은 "이번 연구는 원자 단위 물질 조작이라는 기초 물질과학의 기법을 현대 반도체 기술에 접목해 미래 반도체 기술의 질적 도약을 위한 돌파구를 마련했다는 데 의미가 있다"고 밝혔다. 과기정통부 연구개발정책실장은 원천기술이 산업 경쟁력으로 이어지도록 기초·원천 연구 지원을 아끼지 않겠다고 말했다.</p>', '과기정통부는 기초과학연구원(IBS) 연구팀이 2차원 반도체의 원자를 선택적으로 바꿔 하나의 박막에 반도체·절연체·준금속 영역을 만드는 트랜지스터 제작 기술을 개발해 학술지 사이언스에 실었다고 밝혔다.', '/sites/newstoday/photos/ntd-industry4-general-1.webp', '2026-10-16T09:20:00+09:00'::timestamptz, array['반도체','2차원반도체','트랜지스터','기초과학연구원','사이언스']::text[], 'in_review'),
  ('industry4-general', '인천 지하철 1·2호선 와이파이 5G로 고도화…과기정통부, 현장 체험 행사', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 21일 보도자료에서 시범노선인 인천 지하철 1·2호선의 지하철 와이파이 고도화(LTE에서 5G로) 사업을 마쳤다고 밝혔다. 과기정통부는 이날 인천지하철 2호선 운연역부터 인천시청역까지 구간에서 개선된 통신 품질을 국민과 함께 체험하는 행사를 열었다.</p><p>이번 행사는 통신 3사가 모두 5G 기반 지하철 와이파이 서비스를 개시한 첫 노선에서 성과를 공유하기 위해 마련됐다. 과기정통부는 정부와 국회, 지역, 산업계가 협력해 추진해 온 사업이라고 설명했다.</p><img src="/sites/newstoday/photos/ntd-industry4-general-2.webp" alt="인천 지하철 2호선 전동차(자료사진). 사진: 분당선M/위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 인천 지하철 2호선 전동차(자료사진). 사진: 분당선M/위키미디어 공용 (CC BY-SA 4.0)</em></p><p>행사에는 류제명 과기정통부 2차관과 국회의원, 인천광역시장, 인천교통공사 사장, 통신 3사 관계자, 국민체험단 11명 등이 참여했다. 참석자들은 열차를 타고 7개 역을 이동하며 와이파이로 웹서핑과 사회관계망서비스(SNS) 이용, 영상 시청을 체험했다.</p><p>과기정통부는 현장 체험 결과 웹서핑이나 SNS를 이용할 때 응답 속도가 빨라진 것을 체감할 수 있었다고 밝혔다. 다수 이용자가 동시에 접속한 상황에서도 고화질 동영상을 끊김 없이 볼 수 있는 등 데이터 사용량이 많은 서비스를 원활하게 이용할 수 있었다는 설명이다.</p><p>류제명 2차관은 "통신 3사 및 지역교통공사와 협력하여 5G 기반의 지하철 와이파이가 전국으로 확대될 수 있도록 정책적 지원을 하겠다"고 밝혔다. 이번 시범노선은 인천 지하철 1·2호선이다.</p>', '과기정통부는 시범노선인 인천 지하철 1·2호선의 와이파이를 LTE에서 5G로 고도화했다며, 21일 2호선 구간에서 국민체험단과 함께 개선된 품질을 확인하는 행사를 열었다고 밝혔다.', '/sites/newstoday/photos/ntd-industry4-general-2.webp', '2026-10-22T07:41:00+09:00'::timestamptz, array['5G','지하철와이파이','인천지하철','통신','과기정통부']::text[], 'in_review'),
  ('industry4-general', '9월 ICT 수출 751.5억 달러 역대 최고…반도체 603.3억 달러로 견인', '<p>@@BYLINE@@&nbsp;과학기술정보통신부와 산업통상부는 14일 9월 정보통신산업(ICT) 수출입 동향을 발표했다. 9월 수출은 751.5억 달러로 전년 동월(254.0억 달러)보다 195.8% 늘었고, 수입은 214.3억 달러로 55.3% 늘어 무역수지는 537.1억 달러 흑자를 기록했다.</p><p>ICT 수출은 사상 처음으로 700억 달러를 넘었고, 무역수지도 역대 처음 500억 달러대 흑자를 냈다. 기존 최고 수출액은 8월의 599.8억 달러였다. ICT 수출은 국가 전체 수출액 1,209.4억 달러의 62.1%를 차지해 지난달에 이어 60%대 비중을 유지했다.</p><img src="/sites/newstoday/photos/ntd-industry4-general-3.webp" alt="반도체 웨이퍼(자료사진). 사진: Windell Oskay/위키미디어 공용 (CC BY 2.0)"><p><em>▲ 반도체 웨이퍼(자료사진). 사진: Windell Oskay/위키미디어 공용 (CC BY 2.0)</em></p><p>품목별로는 반도체 수출이 603.3억 달러(262.8% 증가)로 ICT 수출의 80.3%를 차지했다. 두 부처는 인공지능 기반 시설(AI 인프라) 수요 확대에 따른 고부가 제품 판매 증가와 메모리 고정거래 가격 상승세 지속으로 반도체가 월별 최고 실적을 2개월 연속 경신했다고 설명했다.</p><p>컴퓨터·주변기기 수출은 71.6억 달러로 393.0% 늘었다. 인공지능 데이터센터 투자 확대가 이어지면서 반도체 기반 보조기억장치(SSD) 수출이 67.7억 달러로 532.0% 증가한 영향이 컸다. 휴대폰은 부분품 수출과 고가 완제품 판매량이 늘어 19.0억 달러로 28.2% 증가했다.</p><p>반면 디스플레이 수출은 17.0억 달러로 11.5% 줄었다. 일부 스마트폰 신제품 출시 일정이 조정되면서 유기발광다이오드(OLED) 수요가 감소한 영향이다. 통신장비 수출도 2.3% 감소했다.</p><p>지역별로는 미국(420.1% 증가), 중국(홍콩 포함, 228.9%), 인도(104.3%), 베트남(66.8%), 일본(119.6%), 대만(110.9%), 유럽연합(128.5%) 등 주요 국가·지역 수출이 모두 늘었다. 9월 ICT 수입은 반도체(94.5% 증가), 휴대폰(40.9%), 컴퓨터·주변기기(48.4%) 등 주요 품목이 늘어 214.3억 달러를 기록했다.</p>', '과기정통부와 산업통상부는 9월 정보통신산업 수출이 751.5억 달러로 사상 처음 700억 달러를 넘었고 무역수지 흑자는 537.1억 달러라고 발표했다. 반도체가 80.3%를 차지했다.', '/sites/newstoday/photos/ntd-industry4-general-3.webp', '2026-10-15T09:30:00+09:00'::timestamptz, array['ICT수출','반도체','무역수지','과기정통부','산업통상부']::text[], 'in_review'),
  ('industry4-general', '과기정통부, 개방형 양자 테스트베드 3개 거점으로 확대…올해 74억 원 투입', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 21일 한국지능정보사회진흥원(NIA)과 함께 판교 기업지원허브에서 「개방형 양자 테스트베드 고도화·확산 사업」 착수보고회를 열었다고 밝혔다. 국내 양자통신 기술·제품의 실증 기회를 넓히고 상용화와 해외 진출 기반을 강화하는 사업이다.</p><p>개방형 양자 테스트베드는 기업과 연구기관이 자체적으로 갖추기 어려운 양자암호통신 시험망과 고가의 측정 장비를 공동으로 활용해 기술·제품의 성능을 확인하는 실증 공간이다. 과기정통부와 NIA는 2024년부터 서울-판교-대전 구간에 이 환경을 조성하고 시험·검증과 기술 컨설팅을 지원해 왔다.</p><img src="/sites/newstoday/photos/ntd-industry4-general-4.webp" alt="광케이블 단면(자료사진, 일부 잘라 사용). 사진: Asurnipal/위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 광케이블 단면(자료사진, 일부 잘라 사용). 사진: Asurnipal/위키미디어 공용 (CC BY-SA 4.0)</em></p><p>이번 사업은 기존 실증 기반을 기술 성숙도와 활용 목적에 따라 상용·해외·미래 거점으로 나눠 확대한다. 상용·미래 거점에는 KT 주관 컨소시엄이, 해외 거점에는 SK브로드밴드 주관 컨소시엄이 수행기관으로 선정됐다. 사업은 2026년부터 2028년까지 3년간 추진되며 올해는 정부출연금 37.5억 원과 민간부담금 36.5억 원 등 74억 원이 투입될 예정이다.</p><p>상용 거점은 기존 시험망을 올해 대구로 확장하고 2027년 광주·부산, 2028년 강원권까지 단계적으로 넓힌다. 연구·의료·금융 분야 데이터 전송에 양자암호통신을 적용하고, 서로 다른 제조사의 국산 장비 간 연동을 검증하는 데 중점을 둔다.</p><p>해외 거점은 싱가포르, 폴란드, 불가리아 등의 양자 테스트베드와 연계해 국가 간 양자보안 실증을 추진한다. 국내와 해외 현지 구간에는 양자키분배(QKD)를, 장거리 국제 구간에는 양자내성암호(PQC)를 적용해 연구 데이터 전송과 미래항공교통(UAM) 데이터 보호 등을 실증한다. 미래 거점은 장거리 무선 양자암호통신과 여러 지점 간 양자얽힘 분배 등 차세대 양자통신 기술의 실증 환경 구축을 목표로 한다.</p><p>정부는 지난 8월 양자를 미래성장동력 「7대 SEED 프로젝트」의 차세대 프런티어 분야로 선정했다. 이날 착수보고회에서는 거점별 구축·실증 계획과 테스트베드 이용 사례를 공유하고 기업 간담회로 현장 의견을 들었다. 과기정통부 기초원천연구정책관은 "양자기술의 상용화를 앞당기기 위해서는 기업이 다양한 환경에서 기술과 제품을 검증할 수 있도록 실증 기반을 넓히는 것이 중요하다"고 밝혔다.</p>', '과기정통부는 한국지능정보사회진흥원(NIA)과 함께 21일 ''개방형 양자 테스트베드 고도화·확산 사업'' 착수보고회를 열고 상용·해외·미래 3개 거점으로 실증 기반을 넓힌다고 밝혔다.', '/sites/newstoday/photos/ntd-industry4-general-4.webp', '2026-10-22T07:20:00+09:00'::timestamptz, array['양자통신','양자암호','테스트베드','과기정통부','NIA']::text[], 'in_review'),
  ('industry4-general', '정보보호 공시 의무, 2027년부터 전체 상장사로 확대…시행령 개정안 의결', '<p>@@BYLINE@@&nbsp;과학기술정보통신부는 20일 정보보호 공시 의무 대상을 확대하는 「정보보호산업의 진흥에 관한 법률 시행령」 개정안이 이날 국무회의를 통과했다고 밝혔다. 개정 시행령은 2027년 1월 1일부터 적용된다.</p><p>정보보호 공시는 기업의 정보보호 투자·인력, 관련 인증·평가·점검 및 활동 현황을 공개하는 제도로, 2022년부터 사업 분야와 매출액, 이용자 수 등이 일정 기준에 해당하는 기업에 의무화됐다. 이번 개정은 연이은 사이버 침해사고를 계기로 지난해 10월 관계부처 합동으로 발표한 「범부처 정보보호 종합대책」의 후속 조치 가운데 하나다.</p><img src="/sites/newstoday/photos/ntd-industry4-general-5.webp" alt="서버실 내부(자료사진). 사진: Carl Lender/위키미디어 공용 (CC BY 2.0)"><p><em>▲ 서버실 내부(자료사진). 사진: Carl Lender/위키미디어 공용 (CC BY 2.0)</em></p><p>개정안은 상장기업에 적용하던 ''매출액 3,000억 원 이상'' 요건을 없애 매출 규모와 관계없이 유가증권시장(KOSPI)과 코스닥시장(KOSDAQ)의 전체 상장법인을 의무 대상에 포함한다. 기업인수목적회사(SPAC)는 제외한다. 정보보호 관리체계(ISMS) 인증 의무 대상자를 새로 추가하고, 그동안 제외됐던 공공기관·소기업·금융회사·전자금융업자 등에 대한 예외 규정도 삭제한다.</p><p>다만 중소기업기본법 시행령에 따른 소기업은 경영 여건을 고려해 2년 뒤인 2029년 1월 1일부터 공시 의무를 적용한다. 이용자 수 산정 기준은 기존 ''전년도 말 직전 3개월간 하루 평균 이용자 수''에서 ''전년도 전체 하루 평균 이용자 수''로 바뀐다.</p><p>과기정통부는 신규 의무 대상 기업의 부담을 덜기 위해 개정 내용을 반영한 정보보호 공시 가이드라인을 제공하고 컨설팅을 지원할 계획이다. 온라인 상시 상담과 교육, 지역 순회 방문 교육도 함께 운영한다. 개정안은 입법예고와 공청회, 이해관계자 간담회를 거쳐 기업·전문가·국민 의견을 수렴해 마련했다. 배경훈 부총리 겸 과기정통부 장관은 "정보보호 공시는 국민의 알 권리를 보장하고, 기업의 자발적인 정보보호 투자를 유도하는 중요한 제도"라며 의무 대상 확대를 계기로 정보보호 투자가 활성화되기를 기대한다고 밝혔다.</p>', '과기정통부는 정보보호 공시 의무 대상을 매출액과 관계없이 전체 상장법인과 ISMS 인증 의무 대상자로 넓히는 시행령 개정안이 20일 국무회의를 통과했다고 밝혔다. 2027년 1월 시행된다.', '/sites/newstoday/photos/ntd-industry4-general-5.webp', '2026-10-20T10:40:00+09:00'::timestamptz, array['정보보호공시','사이버보안','시행령','상장사','과기정통부']::text[], 'in_review'),
  ('bigdata', '건강검진 대상 아니어도 국가 통합 바이오 빅데이터 사업 참여 가능', '<p>@@BYLINE@@&nbsp;보건복지부와 과학기술정보통신부, 산업통상부, 질병관리청은 15일 보도자료에서 국가 통합 바이오 빅데이터 구축 사업의 참여 대상을 확대했다고 밝혔다. 그동안 국가건강검진 대상자만 참여할 수 있었으나, 앞으로는 검진 대상이 아니어도 연구 참여를 희망하는 국민이 참여자 모집기관의 검사 절차를 거쳐 사업에 참여할 수 있다.</p><p>이 사업은 국민이 기증한 건강·유전정보를 모아 안전하게 연구에 개방하는 것이다. 부처들은 축적된 데이터가 한국형 독자 의료 인공지능(소버린 의료 AI) 구축은 물론 혁신 신약과 첨단 의료기기 개발, 맞춤형 정밀의료 실현에 활용될 수 있다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-bigdata-1.webp" alt="생체 자료 기증 행사가 열린 신촌세브란스병원 전경(자료사진). ⓒ Bak1999/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 생체 자료 기증 행사가 열린 신촌세브란스병원 전경(자료사진). ⓒ Bak1999/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>사업은 2024년부터 2032년까지 유전체·임상·공공 데이터를 포함한 100만 명 규모의 바이오 빅데이터를 구축하는 연구개발 사업이다. 1단계(2024~2028년)에서 77만 2천 명, 2단계(2029~2032년)에서 총 100만 명을 목표로 하며, 일반인 58만 5천 명, 중증질환자 14만 명, 희귀질환자 4만 7천 명을 의료기관과 검진센터를 통해 모집한다.</p><p>참여자에게서 채취한 혈액·소변 등 검체로는 DNA와 혈청 등 인체자원을 만들어 질병관리청 국립중앙인체자원은행에 보존한다. 참여자의 유전체·임상·공공 데이터는 통합해 한국보건의료정보원 인체유래물은행에 구축하며, 연구자가 인체자원과 데이터 분양을 신청하면 심의를 거쳐 연구에 활용할 수 있도록 개방한다.</p><p>보건복지부는 참여 기준 확대를 알리기 위해 15일 오전 10시 연세대학교 신촌세브란스병원에서 생체 자료(바이오 데이터) 기증 행사를 열었다. 한국보건산업진흥원 국가통합바이오빅데이터구축사업단이 마련한 행사에는 정은경 보건복지부 장관과 하정우 국가인공지능전략위원회 부위원장 및 분과위원, 고상백 한국보건산업진흥원장, 세브란스병원 관계자 등 약 40명이 참여 동의와 채혈, 신체 계측 절차를 거쳐 생체 자료를 기증했다.</p><p>이어진 정책 간담회에서는 사업 추진 현황과 11월 1차 데이터 개방 계획을 공유하고, 통합 바이오 빅데이터가 인공지능 시대 미래 의료 혁신의 기반이 되기 위한 정책 방향을 논의했다고 보건복지부는 밝혔다. 정 장관은 "국가 통합 바이오 빅데이터는 국민 한 분 한 분의 참여로 완성되는 공공 자산이다"라고 밝혔다. 또 "11월 첫 개방을 시작으로 데이터가 안전하고 폭넓게 활용되어 의료 혁신의 성과가 국민께 돌아갈 수 있도록 지원하겠다"라고 덧붙였다.</p>', '보건복지부 등 4개 부처는 국가 통합 바이오 빅데이터 구축 사업의 참여 대상을 건강검진 수검자에서 연구 참여를 희망하는 국민으로 넓혔다고 밝혔다. 11월에는 1차 데이터 개방이 계획돼 있다.', '/sites/newstoday/photos/ntd-bigdata-1.webp', '2026-10-15T14:30:00+09:00'::timestamptz, array['바이오빅데이터','보건복지부','의료AI','정밀의료','데이터개방']::text[], 'in_review'),
  ('bigdata', '행안부, 행정서비스 1,658개 제출서류 간소화 완료', '<p>@@BYLINE@@&nbsp;행정안전부는 19일 보도자료에서 중앙부처와 지방정부의 행정서비스 1,658개에 대한 제출서류 간소화를 완료했다고 밝혔다. 국민이 행정서비스를 신청할 때 구비서류를 직접 발급받아 제출해야 했던 불편을 줄이기 위한 조치다.</p><p>제출서류 간소화는 행정·공공기관 간 정보 공유로 다른 기관의 서류를 따로 발급받는 번거로움을 줄이는 정책이다. 신청자가 공무원이 전산망으로 필요한 정보를 직접 확인하는 데 동의하면 별도의 서류 제출 없이 서비스를 신청할 수 있다. 행안부는 행정정보 공동이용과 공공 마이데이터 제도를 활용해 서류 제출 부담을 줄여 왔다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-bigdata-2.webp" alt="행정서비스 신청과 민원 처리가 이뤄지는 주민센터(자료사진, 강릉시 초당동주민센터). ⓒ Mobius6/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 행정서비스 신청과 민원 처리가 이뤄지는 주민센터(자료사진, 강릉시 초당동주민센터). ⓒ Mobius6/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>연도별로는 2024년 421개, 2025년 679개, 올해 3분기 558개 등 모두 1,658개 서비스의 간소화가 이뤄졌다. 행안부는 2024년부터 제출서류 간소화를 중점과제로 관리해 왔으며, 2024년부터 누적 1억 건 이상의 정보 조회로 서류 제출을 줄였다고 밝혔다.</p><p>분야별로는 소상공인·사업자 서비스가 535개(32.3%)로 가장 많았다. 장애인·노인·취약계층·보훈 204개(12.3%), 생활·세금·요금감면 193개(11.6%), 학생·청년·교육훈련 124개(7.5%), 신혼·임신·출산·육아·다자녀 107개(6.5%)가 뒤를 이었다. 처리기관별로는 시·군·구 등 지방정부가 제공하는 서비스가 55.6%를 차지했다.</p><p>행안부는 산후조리비 지원과 치매 치료관리비 지원을 주요 추진 사례로 제시했다. 아울러 공동이용 대상 행정정보를 지난해 174종에서 올해 181종으로 늘렸고, 다수 지방정부가 공통으로 처리하는 행정서비스 143종을 표준화했다고 밝혔다.</p><p>행정정보 공동이용은 민원 처리기관이 민원인의 동의를 받아 구비서류를 받지 않고, 다른 기관이 보유한 정보를 공동으로 이용하는 서비스다. 이용기관은 882곳으로 행정기관 402곳, 공공기관 442곳, 금융기관 38곳이다. 공공 마이데이터는 행정·공공기관이 보유한 본인 행정정보를 본인 또는 제3자에게 제공하는 서비스다.</p><p>행안부는 앞으로도 행정정보 공동이용 대상 정보를 지속적으로 발굴해 서류 간소화를 더욱 확대해 나갈 예정이라고 밝혔다. 윤호중 행정안전부 장관은 "국민께서 보다 쉽고 편리하게 행정서비스를 이용할 수 있도록 서류 간소화를 지속 확대하고, 나아가 국민이 체감하는 진정한 원스톱 행정서비스가 구현될 수 있도록 최선을 다하겠다"라고 밝혔다.</p>', '행정안전부는 행정정보 공동이용과 공공 마이데이터를 활용해 중앙부처와 지방정부의 행정서비스 1,658개에 대한 제출서류 간소화를 마쳤다고 밝혔다. 2024년부터 누적 1억 건 이상 정보가 조회됐다.', '/sites/newstoday/photos/ntd-bigdata-2.webp', '2026-10-19T15:40:00+09:00'::timestamptz, array['행정안전부','제출서류 간소화','행정정보 공동이용','공공 마이데이터','원스톱행정']::text[], 'in_review'),
  ('bigdata', '해수부, 표층수온·해수면 높이 3개월 전망 해설서 시범 제공', '<p>@@BYLINE@@&nbsp;해양수산부는 14일 보도자료에서 15일부터 표층수온과 해수면 높이의 향후 3개월 전망과 주요 원인을 담은 ''해양기후변화 3개월 전망 해설서''를 시범 제공한다고 밝혔다. 바다에서 나타나는 기후변화를 국민이 보다 쉽게 이해하도록 하기 위한 것이라고 설명했다.</p><p>해수부는 「기후·기후변화 감시 및 예측 등에 관한 법률」에 따라 해수온, 염분, 해수면 높이, 엘니뇨, 해빙 등 10개 해양기후요소의 감시·예측 정보를 생산해 지난해 12월부터 해양수산빅데이터플랫폼을 통해 시범적으로 제공해 왔다. 다만 기존 정보는 해역별 예측값과 평년 대비 변화 정도가 중심이어서 일반 국민이 예측 결과의 의미와 원인까지 파악하기에는 어려움이 있었다는 설명이다.</p><img src="/sites/newstoday/photos/ntd-bigdata-3.webp" alt="부산 해운대 앞바다(자료사진, 기사 내용과 직접 관련 없음). ⓒ Mobius6/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 부산 해운대 앞바다(자료사진, 기사 내용과 직접 관련 없음). ⓒ Mobius6/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>이번 해설서에는 동해·서해·남해의 향후 3개월 표층수온과 해수면 높이 전망, 그리고 그 주요 원인이 담겼다. 예를 들어 표층수온이 평년보다 높을 것으로 전망될 때 우리나라 주변 해역의 기온과 바람 등이 수온 변화에 미치는 영향을 함께 설명한다. 해수면 높이에 대해서는 장기적인 해수면 상승 추세와 함께 바람에 따른 난류 유입, 수온 상승에 따른 바닷물의 열팽창 등 주요 요인을 그림과 설명으로 전달한다고 해수부는 밝혔다.</p><p>해설서는 해양수산빅데이터플랫폼을 통해 3개월마다 시범 제공된다. 해양수산부와 국립수산과학원, 국립해양조사원, 한국해양과학기술원, 극지연구소 누리집에서도 이 플랫폼과 연계해 확인할 수 있다. 해수부는 내년에 해양기후변화 감시·예측 전용 플랫폼을 구축해 관련 서비스를 정식으로 제공할 계획이다.</p><p>황준성 해양수산부 해양환경정책관은 "기후변화는 더 이상 먼 미래의 이야기가 아니라 우리의 일상과 밀접하게 연결되어 있다"라고 밝혔다. 이어 앞으로도 국민 눈높이에서 정확하고 알기 쉬운 해양기후정보를 제공하겠다고 덧붙였다.</p>', '해양수산부는 15일부터 동해·서해·남해의 표층수온과 해수면 높이 3개월 전망과 그 원인을 담은 해설서를 해양수산빅데이터플랫폼에서 시범 제공한다고 밝혔다. 내년에는 전용 플랫폼 구축이 계획돼 있다.', '/sites/newstoday/photos/ntd-bigdata-3.webp', '2026-10-14T14:10:00+09:00'::timestamptz, array['해양수산부','해양기후','빅데이터플랫폼','표층수온','해수면']::text[], 'in_review'),
  ('bigdata', '올해 쌀 예상생산량 351만 8천 톤, 전년보다 0.6% 감소 전망', '<p>@@BYLINE@@&nbsp;국가데이터처는 8일 보도자료에서 2026년 쌀 예상생산량이 351만 8천 톤으로 전년(353만 9천 톤)보다 2만 1천 톤, 0.6% 감소할 전망이라고 밝혔다. 이번 수치는 논벼와 밭벼의 예상 생산량을 표본조사해 추정한 결과다.</p><p>조사는 9월 10일부터 22일까지 진행됐다. 국가데이터처는 조사 이후 기상 여건에 따라 수치가 달라질 수 있고, 재배면적과 생산량은 11월 공표 예정인 ''2026년 쌀 생산량 조사 결과''에서 확정된다고 설명했다. 수치는 현백률 92.9%를 기준으로 하며 표본조사 결과에는 표본오차와 비표본오차가 포함돼 있다.</p><img src="/sites/newstoday/photos/ntd-bigdata-4.webp" alt="추수를 앞두고 벼가 익어가는 논(자료사진, 전북 완주). ⓒ Shamus7792003/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 추수를 앞두고 벼가 익어가는 논(자료사진, 전북 완주). ⓒ Shamus7792003/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>재배면적은 67만 ha로 전년의 67만 8천 ha보다 1.1% 줄었다. 국가데이터처는 전략작물직불제와 논 타작물 전환사업 등 쌀 적정 생산 대책이 추진되면서 재배면적이 감소했다고 밝혔다.</p><p>10a당 예상 생산량은 525kg으로 전년의 522kg보다 0.5% 늘었다. 국가데이터처는 잦은 강우로 병충해가 컸던 전년과 달리 가지치는 시기와 벼 낟알이 형성되는 시기의 기상 여건이 양호해 포기당 이삭 수와 이삭당 낟알 수가 늘었고, 벼알이 여무는 9월의 일조시간도 충분해 생산량이 소폭 증가할 것으로 예상했다고 설명했다.</p><p>9월 1일부터 27일까지 일조시간은 지난해 130.3시간에서 올해 187.6시간으로 늘었다. 포기당 이삭 수는 22.1개에서 22.2개, 이삭당 낟알 수는 85.8개에서 86.4개로 각각 증가했다.</p><p>시도별 쌀 예상생산량은 전남광주가 73만 8천 톤으로 가장 많았고, 충남이 68만 9천 톤, 전북이 53만 3천 톤으로 뒤를 이었다. 국가데이터처는 조정 현백률 90.4%를 적용하면 올해 예상생산량은 342만 4천 톤으로 전년의 344만 4천 톤보다 적다고 함께 제시했다.</p>', '국가데이터처는 2026년 쌀 예상생산량이 351만 8천 톤으로 전년보다 2만 1천 톤 줄어들 전망이라고 밝혔다. 재배면적은 1.1% 줄고 10a당 생산량은 0.5% 늘었으며, 시도별로는 전남광주가 가장 많았다.', '/sites/newstoday/photos/ntd-bigdata-4.webp', '2026-10-08T14:20:00+09:00'::timestamptz, array['국가데이터처','쌀 예상생산량','농작물생산조사','통계','벼 재배면적']::text[], 'in_review'),
  ('bigdata', '해수부, AI·공공데이터 활용 어업 현장 서비스 3종 선보여', '<p>@@BYLINE@@&nbsp;해양수산부는 14일 보도자료에서 인공지능(AI)과 공공데이터 등 디지털 기술을 활용한 현장 밀착형 서비스 3종을 새로 선보인다고 밝혔다. 어업인이 일일이 찾아봐야 했던 복잡한 정보와 까다로운 계산 과정을 간소화하고, 현장의 위험 요소를 미리 파악해 선제적으로 대응할 수 있도록 하는 데 중점을 뒀다고 설명했다.</p><p>첫 번째는 AI 기반 어선·어선원 사고 예방 서비스다. ''능동형 어선원 안전관리 시스템''은 과거 사고 통계와 실시간 기상정보를 종합·분석해 사고 예방 정보를 제공한다. 어선원에게는 카카오 알림톡 등으로 상황에 맞는 정보를 안내하고, 어선원의 안전과 보건을 관리하는 안전감독관에게는 고위험 어선의 특별점검 정보를 제공한다.</p><img src="/sites/newstoday/photos/ntd-bigdata-5.webp" alt="부산항에 정박한 어선들(자료사진, 2012년 촬영). ⓒ calflier001/Wikimedia Commons (CC BY-SA 2.0)"><p><em>▲ 부산항에 정박한 어선들(자료사진, 2012년 촬영). ⓒ calflier001/Wikimedia Commons (CC BY-SA 2.0)</em></p><p>일반 국민도 ''조업정보알리미'' 앱을 설치한 뒤 ''조업 안전해(海)'' 기능을 이용하면 출어 해역의 위험도를 실시간으로 확인할 수 있다. 해수부는 앞으로 별도 앱 설치 없이 ''조업 안전해(海)''로 바로 연결되는 기능을 추가로 개발할 예정이라고 밝혔다.</p><p>두 번째는 예상 폐업지원금 모의계산 서비스 ''척척감척''이다. 감척사업 참여를 희망하는 어업인이 감정평가 전에 선령·톤수, 어획량, 판매단가, 어업경비 등을 입력하면 수산업법 시행령 별표 10의 계산식을 적용한 모의계산 결과가 나온다. 해수부는 이 결과가 참고용이며 최종 지급액은 손실액조사기관과 감정평가사 등의 감정평가를 거쳐 확정된다고 설명했다.</p><p>세 번째는 수산용 의약품의 적정 사용을 돕는 ''수산물 헬스케어 알리미''다. 양식 어업인이 사진·음성·간편검색으로 약품의 기본 정보와 용법·용량을 확인하고 적정 투여량과 예상 출하 가능일을 계산할 수 있다. 현재 위치를 기준으로 수온과 위험 정보, 인근 진료·병성감정기관 정보도 제공한다.</p><p>이번 서비스 3종은 해수부 직원들이 현장의 어려움과 행정적 불편을 해결하고자 제안한 아이디어를 바탕으로 마련됐고, 일부 서비스는 직원들이 AI를 활용해 직접 개발에 참여했다. 해수부는 앞으로 현장 의견을 반영해 서비스의 정확성과 이용 편의성을 보완하고, 보안성 등을 점검해 지속적으로 개선해 나가겠다고 밝혔다.</p>', '해양수산부는 과거 사고통계와 실시간 기상정보를 분석하는 어선원 안전 서비스와 폐업지원금 모의계산, 수산용 의약품 사용 지원 등 인공지능·공공데이터 기반 어업 현장 서비스 3종을 선보인다고 밝혔다.', '/sites/newstoday/photos/ntd-bigdata-5.webp', '2026-10-14T16:20:00+09:00'::timestamptz, array['해양수산부','어선원 안전','공공데이터','인공지능','수산업']::text[], 'in_review'),
  ('world-issue', '한-EU 에너지·환경·기후변화 작업반 회의, 그린 파트너십 논의', '<p>@@BYLINE@@&nbsp;외교부는 21일 보도자료에서 20일 서울 외교부에서 화상 병행으로 제8차 한-유럽연합(EU) 에너지·환경·기후변화 작업반 회의가 열렸다고 밝혔다. 회의는 황준식 외교부 기후환경과학외교국장과 마리아 카스티요 페르난데즈 유럽대외관계청(EEAS) 인도태평양 특사가 수석대표로 공동 주재했다.</p><p>우리 측에서는 외교부, 기후에너지환경부, 해양수산부 등 관계부처가, EU 측에서는 기후행동총국, 에너지총국, 환경총국 등 EU 집행위원회 담당자들이 참석했다. 이 작업반은 한-EU 기본협력협정에 따라 기후변화, 청정에너지 전환, 순환경제 등 분야의 논의를 위해 2018년 설립됐다.</p><img src="/sites/newstoday/photos/ntd-world-issue-1.webp" alt="유럽연합(EU) 집행위원회 본부 건물이 있는 벨기에 브뤼셀의 베를레몽 건물(자료사진, 회의 장소 아님). ⓒ almathias/Wikimedia Commons (CC0)"><p><em>▲ 유럽연합(EU) 집행위원회 본부 건물이 있는 벨기에 브뤼셀의 베를레몽 건물(자료사진, 회의 장소 아님). ⓒ almathias/Wikimedia Commons (CC0)</em></p><p>외교부에 따르면 양측은 기후위기가 깊어지고 국제정세가 변하는 가운데 에너지·환경·기후변화 분야 협력이 중요하다는 점을 재확인하고, 한-EU 그린 파트너십을 지속 발전시키기로 했다. 정책 동향을 서로 공유하고 양자·다자 차원의 협력 방안도 논의했다.</p><p>기후변화 분야에서는 국가 온실가스 감축목표(NDC) 이행과 배출권거래제 등 국내 정책 동향을 공유했다. 파리협정의 효과적 이행과 제31차 유엔기후변화협약 당사국총회(COP31) 등 다자 무대에서의 협력을 강화하기로 했다.</p><p>에너지 분야에서는 재생에너지 확대, 전기화, 해상풍력 등 청정에너지 전환 관련 정책과 경험을 공유했다. 글로벌 전기화 협력 플랫폼 ''전기화 지금(Electrify Now)'' 등 다자 이니셔티브를 통한 협력도 이어가기로 했다고 외교부는 밝혔다.</p><p>환경 분야에서는 생물다양성, 순환경제, 유해화학물질관리 등 주요 환경 정책과 다자환경협약 현안을 놓고 의견을 교환했다. 특히 순환경제 분야에서는 양측의 정책과 제도가 발전하고 있는 만큼 관련 동향을 공유하고 실무 협의를 계속하기로 했다. 외교부는 우리 측이 이번 회의에서 ''한국형 녹색대전환(K-GX)'', ''전기국가(Electro-State)로의 전환'', ''2028년 제4차 유엔 해양 총회 개최'' 등 정부의 주요 정책과 추진 노력을 소개했다고 밝혔다.</p>', '외교부는 20일 서울에서 화상 병행으로 제8차 한-EU 에너지·환경·기후변화 작업반 회의가 열려 기후변화 대응, 청정에너지 전환, 순환경제 등 분야 협력 방안을 논의했다고 밝혔다.', '/sites/newstoday/photos/ntd-world-issue-1.webp', '2026-10-21T15:10:00+09:00'::timestamptz, array['한-EU','그린 파트너십','기후변화','에너지 전환','외교부']::text[], 'in_review'),
  ('world-issue', '한-싱가포르, 제1차 공동운영위원회 열고 협력 방안 논의', '<p>@@BYLINE@@&nbsp;외교부는 16일 보도자료에서 박윤주 외교부 1차관이 15일 싱가포르에서 앨버트 추아(Albert Chua) 싱가포르 외교부 사무차관과 제1차 한-싱가포르 공동운영위원회를 열었다고 밝혔다. 두 차관은 양자관계, 에너지 공급망 등 경제안보, 고위급 교류, 실질협력, 지역 및 국제정세 등을 협의했다.</p><p>공동운영위원회는 2025년 11월 한-싱가포르 정상회담 성과의 하나로 기존 차관보급 정책협의회를 차관급으로 격상하기로 한 이후 처음 열린 회의다. 두 나라가 2025년 11월 관계를 전략적 동반자 관계로 격상한 뒤 열린 첫 회의이기도 하다고 외교부는 설명했다.</p><img src="/sites/newstoday/photos/ntd-world-issue-2.webp" alt="싱가포르 도심 전경(자료사진, 회의 장소 아님). ⓒ Bruce Poon/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 싱가포르 도심 전경(자료사진, 회의 장소 아님). ⓒ Bruce Poon/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>박 차관은 지난 1년간 이뤄진 고위급 교류를 언급하며 2027년 싱가포르가 아세안 의장국을 맡는 만큼 더 빈번하고 긴밀한 고위급 소통이 이어지기를 기대한다고 밝혔다. 외교부는 고위급 교류로 2025년 11월 로렌스 웡 싱가포르 총리의 공식 방한, 올해 3월 이재명 대통령의 싱가포르 국빈 방문, 올해 5월 비비안 발라크리쉬난 싱가포르 외교장관의 공식 방한을 들었다.</p><p>두 차관은 정치·안보·공공행정, 경제·통상, 녹색경제·에너지전환, 첨단기술·연구개발, 인적교류 등 5대 중점 협력 분야의 진전 상황을 점검하고 실질적이고 미래지향적인 협력 방안을 논의했다. 이 5대 분야는 2025년 11월 ''한-싱가포르 전략적 동반자 관계 수립에 관한 공동성명''에 담긴 중점 협력 분야다.</p><p>외교부에 따르면 두 차관은 지난 3월 정상회담의 합의를 토대로 진행 중인 자유무역협정(FTA) 개선 협상이 순조롭게 진행되고 있다고 평가했다. 싱가포르는 우리나라가 아세안 국가 중 처음으로 FTA를 체결해 2006년 발효한 나라다. 양측은 사이버안보와 초국가범죄 등 비전통 안보 위협에 양자뿐 아니라 다자협의체를 통해서도 계속 협력하고, 디지털경제와 녹색경제·에너지전환, 인공지능(AI) 등 신산업 분야 협력을 강화하기로 했다.</p><p>박 차관은 방산과 인프라 분야에서 호혜적·전략적 협력이 심화·확대되기를 희망한다고 밝혔다. 또 연내 조성이 추진 중인 ''K-글로벌 벤처펀드(K-VCC)''를 통해 스타트업 생태계가 구축되기를 기대한다고 말했다. 외교부는 우리 정부가 3월 정상회담을 계기로 열린 ''한-싱 커넥트 서밋''에서 2030년까지 3억 달러 규모의 펀드 조성 계획을 발표했다고 설명했다.</p><p>두 차관은 2027년 싱가포르의 아세안 의장국 수임과 우리나라의 차기 한-아세안 대화조정국 수임을 계기로 한-아세안 관계 발전을 위한 소통과 협력 강화에 기대를 나타냈고, 한반도와 주요 지역·국제정세에 대해서도 의견을 교환했다. 외교부는 앞으로도 싱가포르와 상호 관심 분야에서 전략적 협력을 확대해 나갈 예정이라고 밝혔다.</p>', '외교부는 박윤주 1차관이 15일 싱가포르에서 앨버트 추아 싱가포르 외교부 사무차관과 제1차 한-싱가포르 공동운영위원회를 열고 양자관계와 경제안보, 고위급 교류 등을 협의했다고 밝혔다.', '/sites/newstoday/photos/ntd-world-issue-2.webp', '2026-10-16T14:20:00+09:00'::timestamptz, array['한-싱가포르','공동운영위원회','외교부','아세안','전략적 동반자 관계']::text[], 'in_review'),
  ('world-issue', '정부, CEPI·Unitaid와 2,800만 달러 규모 기여약정서 체결', '<p>@@BYLINE@@&nbsp;외교부는 20일 보도자료에서 장욱진 글로벌다자외교조정관이 이날 감염병혁신연합(CEPI)과 국제의약품구매기구(Unitaid)의 이사회 의장을 각각 면담하고 글로벌 보건협력 강화 방안을 논의했다고 밝혔다. 면담은 「2026 세계 바이오서밋」 참석을 계기로 방한한 제인 홀튼 CEPI 이사회 의장, 안클레르 앙푸르 Unitaid 이사회 의장과 이뤄졌다.</p><p>이번 면담을 계기로 우리 정부는 두 기구와 총 2,800만 달러 규모의 기여약정서를 체결하고, 에볼라 대응과 글로벌 보건안보 강화를 위한 협력을 확대하기로 했다. CEPI에는 에볼라 대응 지정기여금 1,000만 달러와 정규재원 500만 달러 등 총 1,500만 달러, Unitaid에는 에볼라 대응 지정기여금 800만 달러와 정규재원 500만 달러 등 총 1,300만 달러다.</p><img src="/sites/newstoday/photos/ntd-world-issue-3.webp" alt="에볼라 바이러스의 전자현미경 이미지(자료사진, 이번 면담·분디부교 바이러스와 직접 관련 없음). ⓒ CDC/Cynthia Goldsmith (퍼블릭 도메인, Wikimedia Commons)"><p><em>▲ 에볼라 바이러스의 전자현미경 이미지(자료사진, 이번 면담·분디부교 바이러스와 직접 관련 없음). ⓒ CDC/Cynthia Goldsmith (퍼블릭 도메인, Wikimedia Commons)</em></p><p>외교부는 CEPI를 신종 감염병 백신 개발과 비축 등을 위한 재원 마련을 목적으로 2017년 다보스포럼을 계기로 출범한 글로벌 보건 파트너십이라고 설명했다. Unitaid는 에이즈, 결핵, 말라리아 등 3대 감염병 관련 의약품의 개발과 보급을 목적으로 2006년 9월 출범한 세계보건기구(WHO) 산하 민관협력 파트너십이다.</p><p>장 조정관은 홀튼 의장과의 면담에서 CEPI가 최근 분디부교 에볼라 바이러스를 포함한 신종 감염병 백신 개발에서 선도적 역할을 하고 있다고 언급했다. 이 과정에서 국내 바이오 기업들과의 협업도 활발히 이뤄지고 있다고 밝혔고, 인공지능(AI)을 활용한 팬데믹 대비 엔진(Pandemic Preparedness Engine for Disease X) 등으로 한-CEPI 파트너십이 계속 확대되기를 기대했다고 외교부는 전했다.</p><p>앙푸르 의장과의 면담에서 장 조정관은 에볼라 등 감염병이 발생했을 때 혁신적인 치료제와 진단 기술을 신속히 도입하는 것이 중요하다고 강조했다. 또 우리 바이오 기업의 혁신 제품이 Unitaid를 통해 중저소득국의 보건제품 접근성 강화에 기여하고 있다고 언급했다. 외교부는 앞으로도 글로벌 보건기구와의 다각적 협력으로 국제보건 연대에 참여하는 한편, 민간의 혁신 역량이 글로벌 보건안보 강화에 기여할 수 있도록 노력하겠다고 밝혔다.</p>', '외교부는 장욱진 글로벌다자외교조정관이 20일 감염병혁신연합과 국제의약품구매기구 이사회 의장을 각각 면담하고 에볼라 대응 등을 위한 총 2,800만 달러 규모 기여약정서를 체결했다고 밝혔다.', '/sites/newstoday/photos/ntd-world-issue-3.webp', '2026-10-20T16:06:00+09:00'::timestamptz, array['외교부','CEPI','Unitaid','에볼라','글로벌 보건']::text[], 'in_review'),
  ('world-issue', '외교부·기후에너지환경부, 카자흐스탄에 물산업 협력사절단 파견', '<p>@@BYLINE@@&nbsp;외교부와 기후에너지환경부는 19일 공동 보도자료에서 19일부터 21일까지 카자흐스탄의 수도 아스타나에 물산업 협력사절단을 파견해 양국 간 물산업 협력을 확대하고 우리 물기업의 현지 시장 진출을 지원한다고 밝혔다. 두 부처는 카자흐스탄을 중앙아시아에 있는 인구 약 2천만 명의 나라로, 천연가스와 우라늄 등 지하자원이 풍부하다고 소개했다.</p><p>사절단에는 외교부, 기후에너지환경부, 한국수자원공사, 한국환경공단과 국내 물기업 9개 사가 참여한다. 사절단은 카자흐스탄 주요 물관리 기관과의 기술 교류, 협력회의, 상·하수도 시설 방문, 현지 실증사업 점검 등을 통해 후속 사업화와 신규 협력사업 발굴을 추진한다.</p><img src="/sites/newstoday/photos/ntd-world-issue-4.webp" alt="카자흐스탄 수도 아스타나 도심을 흐르는 이심강(자료사진, 사절단 방문 시설 아님). ⓒ Matti Blume/Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 카자흐스탄 수도 아스타나 도심을 흐르는 이심강(자료사진, 사절단 방문 시설 아님). ⓒ Matti Blume/Wikimedia Commons (CC BY-SA 4.0)</em></p><p>그동안 양국은 사절단 파견을 통해 수처리 설비와 유량계 등 국내 기술·제품의 현지 실증사업을 추진했고, 가상현실(디지털 트윈) 기반의 스마트 물관리 기술협력 양해각서(MOU)를 체결하는 등 협력 성과를 냈다. 이번 사절단은 이를 바탕으로 현지 실증 제품의 실제 구매와 상용화 가능성을 구체적으로 협의하고, 기존 협력사업을 수출 성과로 잇는 데 중점을 둘 예정이다.</p><p>사절단은 19일 카자흐스탄 수자원관개부, 수자원위원회, 아스타나 상하수도 운영기관 등 주요 물관리 기관과 원탁회의(라운드테이블)를 열어 현지 물관리 정책과 기술 수요를 공유하고 협력 확대 방안을 논의한다. 21일까지는 아스타나 상·하수도 운영기관 관계자를 면담해 기술 도입과 제품 구매 가능성 등 구체적인 협력 방안도 논의할 계획이다.</p><p>붙임 일정에 따르면 19일에는 아스타나 하수처리시설 실증현장을 방문하고, 20일에는 정수처리시설을 견학한 뒤 정수시설 실증현장을 찾는다. 21일에는 상하수도 운영기관 면담과 나자르바예프대학교 기술 교류가 예정돼 있으며, 이 대학에서는 수환경 및 정·하수처리 분야 공동연구와 기술 실증 협력 가능성을 모색한다.</p><p>외교부와 기후에너지환경부는 이번 사절단 파견으로 그간의 기술 교류와 실증사업 성과가 실제 제품 구매와 수출로 이어지도록 협력을 구체화하겠다고 밝혔다. 두 부처는 카자흐스탄의 물관리 수요와 우리 기업의 기술을 연계해 양국 물산업 협력을 지속적으로 확대할 계획이다.</p>', '외교부와 기후에너지환경부는 19일부터 21일까지 카자흐스탄 아스타나에 물산업 협력사절단을 파견해 양국 물산업 협력을 넓히고 국내 물기업 9개 사의 현지 시장 진출을 지원한다고 밝혔다.', '/sites/newstoday/photos/ntd-world-issue-4.webp', '2026-10-19T11:30:00+09:00'::timestamptz, array['카자흐스탄','물산업','외교부','기후에너지환경부','협력사절단']::text[], 'in_review'),
  ('world-issue', '외교부, 일본 대규모 지진 대비 재외공관 신속대응팀 모의훈련', '<p>@@BYLINE@@&nbsp;외교부는 20일 보도자료에서 일본에서 대규모 지진이 발생했을 때 재외국민을 보호하기 위한 현지 재외공관의 대응 태세를 점검하기 위해 19일 주일본대사관에서 모의훈련을 실시했다고 밝혔다. 훈련은 외교부와 관계부처, 공관이 함께하는 신속대응팀 모의훈련과 민관합동 해외안전자문 활동으로 진행됐다.</p><p>훈련에는 주요코하마총영사관과 경찰청·소방청 관계자, 현지 민간전문가가 참여했다. 현지 민간전문가의 맞춤형 안전 자문도 함께 이뤄졌다.</p><img src="/sites/newstoday/photos/ntd-world-issue-5.webp" alt="일본 도쿄의 주일본 한국대사관 건물(자료사진, 2018년 촬영). ⓒ Syced/Wikimedia Commons (CC0)"><p><em>▲ 일본 도쿄의 주일본 한국대사관 건물(자료사진, 2018년 촬영). ⓒ Syced/Wikimedia Commons (CC0)</em></p><p>이번 훈련은 주일본대사관이 일본 지역 거점공관으로서 맡는 역할에 중점을 뒀다. 거점공관인 주일본대사관은 관할지역 밖에서 지진이 발생하면 피해 지역을 관할하는 총영사관에 인력과 물자를 지원하고 대응을 총괄한다.</p><p>외교부·경찰청·소방청 관계자로 구성된 신속대응팀 출장단은 20일 교민 안전간담회를 열었다. 이 자리에서 최근 재난 동향과 재난 발생 시 대응 요령 등 안전정보를 공유하고 공관과의 상시 연락체계를 점검했으며, 재외국민 응급의료상담 서비스도 소개했다.</p><p>외교부는 매년 재외공관과 함께 다양한 위기 상황을 가정한 모의훈련을 실시하고 있다고 밝혔다. 올해 4월에는 케냐에서 해적에 의한 선박 피랍 대응 훈련을, 5월에는 조지아에서 정정불안 심화에 따른 우리 국민 대피 상황을 가정한 훈련을 했다. 외교부는 앞으로도 다양한 해외 위난 상황에 대비한 신속대응팀 모의훈련을 통해 국민의 생명과 안전을 지키기 위한 대응 역량과 유관기관 간 협조체계를 강화해 나갈 예정이라고 밝혔다.</p>', '외교부는 일본에서 대규모 지진이 발생할 때 재외국민을 보호하기 위해 19일 주일본대사관에서 외교부·관계부처·공관 합동 신속대응팀 모의훈련과 민관합동 해외안전자문 활동을 실시했다고 밝혔다.', '/sites/newstoday/photos/ntd-world-issue-5.webp', '2026-10-20T10:41:00+09:00'::timestamptz, array['외교부','재외국민 보호','일본','지진','모의훈련']::text[], 'in_review'),
  ('society-general', '행안부, 내수면 선박·겨울 야외 레저 숨은 위험 분석 보고서 발간', '<p>@@BYLINE@@&nbsp;행정안전부는 22일 보도자료를 통해 하천·호수 등 내수면에서의 선박 운영과 겨울 레저활동에서 발생할 수 있는 잠재 재난위험 요소를 분석한 ‘잠재 재난위험 분석 보고서’를 발간한다고 밝혔다. 선박사고와 겨울 야외 레저활동의 위험 요소를 발굴해 안전관리 사각지대를 개선하는 것이 목적이라고 행안부는 설명했다.</p><p>행안부는 최근 하천과 호수에서 관광과 레저를 즐기는 등 내수면 선박 이용이 늘고 있다고 짚었다. 내수면을 운항하는 선박의 안전관리가 체계적으로 이뤄지지 못하면 자칫 대형 참사로 이어질 위험이 있다는 것이다.</p><img src="/sites/newstoday/photos/ntd-society-general-1.webp" alt="겨울철 얼음 위 레저 현장의 예로, 강원 화천 산천어축제 얼음낚시장(2023년 1월 촬영, 자료사진). ⓒ Republic of Korea(KOCIS) / 위키미디어 공용 (CC BY-SA 2.0)"><p><em>▲ 겨울철 얼음 위 레저 현장의 예로, 강원 화천 산천어축제 얼음낚시장(2023년 1월 촬영, 자료사진). ⓒ Republic of Korea(KOCIS) / 위키미디어 공용 (CC BY-SA 2.0)</em></p><p>보고서는 우리나라 내수면에 다양한 뱃길이 만들어지고 요트와 같은 마리나 선박까지 운항되면서 한정된 수역을 다양한 선박이 이용하게 됐다고 분석했다. 이에 따라 선박충돌과 같은 안전사고에 대비할 필요가 있다고 봤다.</p><p>개선 방안으로는 선박 안전점검 강화와 내수면의 지리·환경적 특성을 고려한 지역 맞춤형 운항 통제 기준 마련이 제시됐다. 내수면을 운항하는 선박의 영업구역이 체계적으로 관리되도록 관계부처 간 정보 공유 체계를 보완해야 한다는 제언도 담겼다.</p><p>겨울 야외 레저활동에 대해서는 기후변화로 기온의 상승과 하강이 반복되면서 얼음의 강도가 약해져 얼음깨짐 등 사고가 발생할 가능성이 있다고 지적했다. 야외 스케이트, 썰매, 빙벽 등반, 빙박(얼음 위 야영) 등이 대상 활동으로 언급됐다.</p><p>현행 겨울철 레저 시설 안전관리 가이드가 실내 시설 중심으로만 되어 있어 야외 시설에 대한 기준도 포함하도록 확대해야 한다는 것이 보고서의 제안이다. 자연얼음을 이용하는 레저활동에 대해서는 위험 상황 정보를 적극 알리도록 했다.</p><p>행안부는 보고서를 관계 기관에 공유하고, 앞으로도 사회에 잠재된 위험요소를 지속적으로 발굴해 보고서를 정기적으로 발간할 예정이라고 밝혔다. 보고서는 국립재난안전연구원 누리집(ndmi.go.kr)에서 누구나 열람할 수 있다. 김광용 재난안전관리본부장은 “우리 사회 곳곳에 숨겨진 재난 위험을 한발 앞서 찾아내고, 관계기관과 함께 안전 관련 제도와 기준을 지속적으로 보완해 나가겠다”고 말했다.</p>', '행정안전부가 하천·호수 등 내수면의 선박 운영과 겨울 야외 레저활동에서 생길 수 있는 잠재 재난위험을 분석한 보고서를 발간한다고 22일 밝혔다. 선박 안전점검 강화 등을 제안했다.', '/sites/newstoday/photos/ntd-society-general-1.webp', '2026-10-22T07:12:00+09:00'::timestamptz, array['행정안전부','내수면','선박안전','겨울 레저','재난안전']::text[], 'in_review'),
  ('society-general', '우수 민간구급차에 인증마크…응급환자이송업 품질인증 시범사업 시작', '<p>@@BYLINE@@&nbsp;보건복지부와 국립중앙의료원 중앙응급의료센터가 이달 21일부터 30일까지 ‘응급환자이송업 품질 인증제 시범사업’에 참여할 업체를 모집한다. 정책브리핑이 20일 정책뉴스로 전한 내용에 따르면 필수 기준을 모두 충족한 뒤 품질평가에서 60점 이상을 받은 업체가 인증마크를 받는다.</p><p>응급환자이송업은 응급의료에 관한 법률에 따라 구급차 등을 이용해 응급환자 등을 이송하는 업이다. 병원 간 환자 이송 등 응급의료체계에서 중요한 역할을 맡고 있다. 시범사업은 법정 기준 준수 여부를 확인하는 데서 나아가 이송서비스의 품질을 종합적으로 평가하고, 업체의 자발적인 서비스 개선을 유도하기 위해 마련됐다.</p><img src="/sites/newstoday/photos/ntd-society-general-2.webp" alt="서울 도심 도로를 달리는 구급차(2018년 촬영, 자료사진). 기사 속 시범사업 대상 업체와는 관련이 없다. ⓒ Kevin.B / 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 서울 도심 도로를 달리는 구급차(2018년 촬영, 자료사진). 기사 속 시범사업 대상 업체와는 관련이 없다. ⓒ Kevin.B / 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>참여 대상은 2023년 1월 1일 이전에 응급환자이송업 허가를 받아 신청 공고일까지 계속 운영 중인 업체다. 행정처분 이력과 이송실적 등 공고에서 정한 자격요건을 충족해야 하며, 관련 법령에 따른 비영리법인도 요건을 갖추면 신청할 수 있다.</p><p>인증심사는 신청 자격 검증을 거쳐 서면심사와 현장심사로 진행된다. 필수영역에서는 인력·시설·자본·장비·기록 등에 관한 법정 기준 준수 여부를 확인하고, 품질영역에서는 운영·인력·장비·감염·기록 등 5개 항목을 평가한다. 이송인력 교육, 장비 관리, 구급차 소독, 이송기록의 신뢰도 등이 주요 심사 내용이다.</p><p>인증을 받으려면 필수영역의 모든 기준을 충족하고, 품질영역에서 총점 60점 이상을 받는 동시에 개별 지표별로 해당 배점의 40% 이상을 받아야 한다. 인증업체에는 인증서와 인증마크를 제공하며 유효기간은 인증일부터 2년이다. 별도 모니터링 지표는 향후 제도 개선을 위한 기초자료로 쓰이며 인증 여부에는 반영하지 않는다.</p><p>신청은 구급차기록관리시스템(AiR)을 통해 받는다. 이후 신청 자격 검증과 서면·현장심사, 인증위원회 심의를 거쳐 12월 중 최종 결과를 발표할 예정이다. 신청 자격과 심사 기준, 제출 서류 등은 구급차기록관리시스템(air.nemc.or.kr) 통합게시판 공지사항과 온라인 설명회 영상에서 확인할 수 있다.</p><p>이중규 보건복지부 공공의료정책관은 “응급환자 이송서비스는 응급의료체계의 중요한 한 축으로, 국민이 안심하고 이용할 수 있는 환경을 마련하는 것이 중요하다”고 밝혔다. 복지부는 시범사업 심사 결과를 바탕으로 이송서비스 품질 개선을 위한 제도적 기반을 마련하겠다는 방침이다.</p>', '보건복지부와 국립중앙의료원 중앙응급의료센터가 응급환자이송업 품질 인증제 시범사업 참여 업체를 이달 21일부터 30일까지 모집한다. 품질평가에서 60점 이상 받은 업체에 인증마크를 준다.', '/sites/newstoday/photos/ntd-society-general-2.webp', '2026-10-20T10:25:00+09:00'::timestamptz, array['보건복지부','응급환자이송업','민간구급차','품질인증','응급의료']::text[], 'in_review'),
  ('society-general', '농지은행 임대수탁 신청 간소화…서명 한 번으로 서류 제출', '<p>@@BYLINE@@&nbsp;농림축산식품부와 한국농어촌공사는 21일부터 농지은행 농지임대수탁 제도를 개편해 신청 절차를 간소화하고, 농업경영체 등록 변경까지 농지은행 한 곳에서 처리한다고 밝혔다. 정책브리핑이 같은 날 정책뉴스로 전한 내용이다. 종이 서류를 내지 않고 서명 한 번으로 신청할 수 있다는 점이 핵심이다.</p><p>기존에는 농지은행에 농지를 맡길 때 휴대전화 본인인증을 거쳐 공공마이데이터로 7종의 서류를 제출해야 했고, 등기부등본은 별도로 발급받아 내야 했다. 개편 이후에는 서명 한 번으로 휴대전화 본인인증 없이 7종의 서류를 제출할 수 있다.</p><img src="/sites/newstoday/photos/ntd-society-general-3.webp" alt="전북 완주군 구이호 인근의 수확을 앞둔 논(2014년 9월 촬영, 자료사진). ⓒ Shamus7792003 / 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 전북 완주군 구이호 인근의 수확을 앞둔 논(2014년 9월 촬영, 자료사진). ⓒ Shamus7792003 / 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>등기부등본은 농지은행 직원이 직접 열람하기 때문에 이용자가 종이 서류를 따로 제출하지 않아도 된다. 고령층은 신분증만으로 지사에서 신청할 수 있다. 농식품부 등은 농지은행 이용자 10명 중 4명 이상이 60대 이상인 만큼 디지털 기기 사용이 익숙하지 않은 고령 농업인의 신청 부담이 줄 것으로 기대했다.</p><p>제출한 정보가 신청서에 자동으로 입력되도록 시스템도 개선했다. 이에 따라 서류 제출부터 계약서 작성까지 걸리는 시간은 평균 9분 30초대에서 4분대로 절반 이상 줄었고, 창구 대기시간도 그만큼 짧아진다고 밝혔다.</p><p>농업경영체 등록 변경 절차도 달라진다. 그동안은 임대수탁 계약 뒤 농업경영체 등록 정보를 바꾸려면 국립농산물품질관리원 지원·사무소를 방문하거나 전화로 신청해야 했다. 21일부터는 임대수탁 신청과 농업경영체 등록 변경 신청을 농지은행에서 함께 처리할 수 있다.</p><p>다만 농업경영체 신규 등록은 기존처럼 국립농산물품질관리원을 방문해 신청해야 한다. 이번 개편은 농지조사 과정에서 나온 임대수탁 이용 불편 의견을 반영한 것이라고 농식품부는 설명했다.</p><p>윤원습 농림축산식품부 농업정책관은 “이번 개편은 농지조사 과정에서 들은 임대수탁 이용 불편 의견을 반영해 서류를 줄이고 절차를 한 곳으로 모은 것”이라고 밝혔다. 이정문 한국농어촌공사 농지관리이사는 “농지은행 임대수탁 제도를 국민 눈높이에 맞춰 개선했다”고 말했다.</p>', '농림축산식품부와 한국농어촌공사가 21일부터 농지은행 농지임대수탁 제도를 개편했다. 종이 서류 없이 서명 한 번으로 신청할 수 있고, 농업경영체 등록 변경도 농지은행 한 곳에서 처리한다.', '/sites/newstoday/photos/ntd-society-general-3.webp', '2026-10-21T09:41:00+09:00'::timestamptz, array['농지은행','농림축산식품부','한국농어촌공사','농지임대수탁','서류 간소화']::text[], 'in_review'),
  ('society-general', '단풍철 국립공원 안전산행…체력에 맞는 탐방로 고르고 보행법 지켜야', '<p>@@BYLINE@@&nbsp;정부가 가을 단풍철 국립공원 탐방객이 늘 것으로 보고 체력에 맞는 탐방로 선택과 지형별 보행법을 지키는 안전산행을 당부했다. 기후에너지환경부 산하 국립공원공단은 16일 가을철 산행 시 주의사항과 올바른 보행법을 소개했다고 밝혔다. 이 내용은 정책브리핑 정책뉴스로도 전해졌다.</p><p>국립공원공단에 따르면 가을 단풍은 일반적으로 10월 중순부터 산 정상부를 중심으로 물들기 시작해 10월 하순부터 11월 초까지 절정을 이룬 뒤 남부지역으로 이어진다. 같은 국립공원에서도 고도와 지형에 따라 시기가 다를 수 있어 탐방 전 단풍 현황과 탐방로 정보를 확인하는 것이 좋다고 했다.</p><img src="/sites/newstoday/photos/ntd-society-general-4.webp" alt="단풍이 물든 설악산국립공원 탐방로(2018년 10월 촬영, 자료사진). ⓒ Christophe95 / 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 단풍이 물든 설악산국립공원 탐방로(2018년 10월 촬영, 자료사진). ⓒ Christophe95 / 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>산행 전에는 자신의 체력에 맞는 탐방로를 고르고 거리, 경사, 소요시간, 노면 상태 등을 미리 확인해야 한다. 국립공원 탐방로는 난이도에 따라 5개 등급으로 나뉘어 체력과 경험에 맞는 코스를 고를 수 있다. 기상상황을 확인하고 등산화, 여벌의 옷, 물, 간식 등 장비를 챙기며, 출발 전 다리와 허리, 어깨 등 주요 근육을 풀어 급경사에 대비하라는 안내도 나왔다.</p><p>가을 산은 기온 변화가 크고 고도 변화가 심해 옷을 여러 겹 준비해야 한다고 했다. 고혈압이나 심장 질환이 있는 탐방객은 중간 쉼터를 충분히 활용해 심장에 무리가 가지 않도록 하고, 해가 지기 전에 하산할 수 있도록 산행시간을 여유 있게 계획하라고 당부했다.</p><p>산행 중 낙엽이 쌓인 곳, 젖은 바위, 목재 계단 등 미끄러운 구간에서는 보폭을 줄이고 천천히 이동해야 한다. 단풍을 감상하거나 사진을 찍을 때도 안전시설과 탐방로를 벗어나지 않아야 하며, 탐방객이 많은 구간에서는 앞사람과 거리를 유지해야 한다. 하산 때는 피로가 쌓여 미끄러지거나 발을 헛디디기 쉬워 더욱 주의가 필요하다고 했다.</p><p>국립공원교육원 산악안전교육센터는 지형별 보행법을 권장했다. 평지에서는 일정한 속도와 리듬을 유지하는 ‘리듬보행’, 오르막에서는 뒷다리를 잠시 펴 체중을 골격으로 지지하는 ‘휴식(레스트)보행’을 활용하라는 것이다. 내리막에서는 무릎을 부드럽게 굽혀 충격을 흡수하는 ‘무릎완충보행’을 하고, 급경사에서는 사선 방향으로 이동하는 지그재그 보행을 활용하면 안정적으로 하산할 수 있다고 했다.</p><p>주대영 국립공원공단 이사장은 “가을은 아름다운 단풍을 즐기기 위해 많은 국민이 국립공원을 찾는 계절”이라고 말했다. 이어 “자신의 체력과 경험에 맞는 탐방로를 선택하고 산행 전 충분히 준비해 안전하고 즐거운 가을 산행을 즐기시길 바란다”고 당부했다.</p>', '국립공원공단이 가을 단풍철을 맞아 체력에 맞는 탐방로 선택과 지형별 보행법 등 안전산행 수칙을 16일 안내했다. 탐방로는 난이도에 따라 5개 등급으로 나뉘며, 낙엽이 쌓인 구간에서는 보폭을 줄이라고 당부했다.', '/sites/newstoday/photos/ntd-society-general-4.webp', '2026-10-16T11:05:00+09:00'::timestamptz, array['국립공원','안전산행','단풍철','국립공원공단','기후에너지환경부']::text[], 'in_review'),
  ('society-general', '송전망 주변마을 ‘햇빛소득’ 지원…입지 선정에 주민 참여 확대', '<p>@@BYLINE@@&nbsp;기후에너지환경부가 송전망이 지나는 마을 주민에게 태양광 발전수익이 돌아가도록 지원체계를 손보고, 송전망 입지를 정하는 과정에도 초기부터 주민 참여를 넓힌다. 기후에너지환경부는 ‘국가기간 전력망 확충 특별법 시행령’ 관련 고시 2건과 ‘송·변전설비 입지선정위원회 구성 및 운영 기준’ 일부개정안을 22일부터 12월 1일까지 입법예고한다고 정책브리핑을 통해 밝혔다.</p><p>이번 개정안은 지난달 15일 국무회의에 보고한 ‘송전망 건설 수용성 제고방안’의 후속 조치다. 기후부는 그동안 송전망 주변지역 주민대표와의 간담회, 대전·금산·안성 등 현장 방문으로 주민 건의사항을 들어왔고 개정안에 이를 반영했다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-society-general-5.webp" alt="인천국제공항 인근 고속도로 옆 송전탑과 송전선(2009년 8월 촬영, 자료사진). 기사 속 사업 지역과는 관련이 없다. ⓒ Shiwon Cho / 위키미디어 공용 (CC BY-SA 2.0)"><p><em>▲ 인천국제공항 인근 고속도로 옆 송전탑과 송전선(2009년 8월 촬영, 자료사진). 기사 속 사업 지역과는 관련이 없다. ⓒ Shiwon Cho / 위키미디어 공용 (CC BY-SA 2.0)</em></p><p>먼저 주민 소득 지원이다. 특별법에 따른 경과 지방정부 지원금(가공선로 1㎞당 20억 원)의 3분의 2 이내를 송·변전설비 주변지역에 배분하고, 해당 마을이 태양광 사업을 하는 경우 설치비용을 우선 반영하도록 한다. 주민이 마을 태양광 사업에 참여해 발전수익을 나눌 수 있게 하겠다는 취지다.</p><p>기후부는 지방정부·한국전력공사와 협력해 주민 참여 의향과 부지·계통접속 등 사업 여건을 갖춘 ‘계통햇빛소득마을 선도사업’을 발굴할 계획이다. 후보 마을의 사업화 가능성과 예상 수익을 검토하고 사업 구상과 참여 절차 안내를 지원한다는 방침이다.</p><p>입지 선정 과정의 투명성도 높인다. 입지선정위원회 구성 전 시군구 단위 주민 설명회를 기존 2차례에서 3차례로 늘리고, 주민의 위원회 참관을 원칙적으로 허용한다. 회의 뒤에는 의결사항과 함께 개인정보 등을 제외한 회의자료를 공개한다.</p><p>입지 대안 검토에 주민이 참여할 기회도 넓어진다. 위원회가 후보 입지를 선정할 때 원칙적으로 2개 이상을 도출해 비교·검토하고, 주민이 대안 경과지나 부지를 서면으로 제안하면 위원회가 심의·의결로 후보 입지로 선정할 수 있도록 근거를 마련한다. 후보 경과지를 검토할 때는 기존 선로나 다른 신설선로와 철탑을 함께 쓰는 방안을 우선 검토할 수 있게 명문화하고, 둘 이상의 사업이 같은 시군구에 걸치면 위원회를 통합하거나 병행해 운영할 수 있도록 한다.</p><p>기후부는 입법·행정예고 기간에 주민과 지방정부 등의 의견을 수렴하고 법제처 심사 등을 거쳐 하위법령과 위원회 고시 개정을 마칠 계획이다. 이재식 전력망정책관은 “송전망 건설 주변 주민이 마을 태양광의 발전수익을 함께 나누고, 사업 초기부터 입지선정에 참여할 수 있게 제도를 개선하겠다”고 전했다.</p>', '기후에너지환경부가 송전망 주변 마을의 태양광 사업 지원과 입지선정위원회 주민 참여 확대를 담은 개정안을 22일부터 12월 1일까지 입법예고한다. 주민 설명회는 기존 2회에서 3회로 늘린다.', '/sites/newstoday/photos/ntd-society-general-5.webp', '2026-10-21T14:20:00+09:00'::timestamptz, array['송전망','햇빛소득마을','기후에너지환경부','전력망','주민참여']::text[], 'in_review'),
  ('feature-special', '통상변화대응법 개정 시행, 외국 통상조치 피해기업 지원 무엇이 달라지나', '<p>@@BYLINE@@&nbsp;산업통상부는 22일 ‘통상환경변화 대응 및 지원 등에 관한 법률’(통상변화대응법) 개정 법령을 이날부터 시행한다고 밝혔다. 정책브리핑이 정책뉴스로 전한 내용에 따르면 외국의 통상조치로 피해를 입은 기업도 지원 대상에 들어가고, 판로 개척 지원이 새로 더해졌다.</p><p>먼저 누가 대상인지다. 기존에는 정부가 체결한 통상조약 등의 이행으로 부정적 영향을 받았거나 받을 우려가 있는 기업만 지원했다. 앞으로는 다른 국가가 자국 법령에 따라 취한 무역·통상 관련 조치로 피해를 입었거나 입을 우려가 있는 기업까지 지원 대상이 확대됐다.</p><img src="/sites/newstoday/photos/ntd-feature-special-1.webp" alt="수출 컨테이너가 쌓인 부산항 컨테이너 터미널(2006년 촬영, 자료사진). 기사 속 특정 기업·항만과는 관련이 없다. ⓒ Niels Johannes / 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 수출 컨테이너가 쌓인 부산항 컨테이너 터미널(2006년 촬영, 자료사진). 기사 속 특정 기업·항만과는 관련이 없다. ⓒ Niels Johannes / 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>무엇이 달라지는지도 있다. 기존 자금 융자와 기술·경영 혁신 지원(컨설팅)에 더해, 통상변화대응지원기업의 경쟁력 확보를 돕는 판로개척 지원사업을 추진할 수 있는 법적 근거가 새로 생겼다.</p><p>지원은 어디서 받는지도 정리됐다. 중소벤처기업진흥공단이 수행하는 통상변화대응지원센터의 기능에 판로 개척 지원 업무가 추가됐다. 산업부는 이에 따라 지원 신청 안내부터 융자, 컨설팅, 판로 개척 지원까지 한 곳에서 받을 수 있는 원스톱 종합 지원 체계가 구축됐다고 설명했다.</p><p>시행 시기는 22일부터다. 산업부는 이번 개정에 따라 외국 통상조치로 어려움을 겪는 기업을 신속하게 지원할 수 있을 것으로 기대했다.</p><p>통상변화대응법은 기존 ‘무역조정 지원 등에 관한 법률’의 제목을 2024년 2월 바꿔 시행 중인 법이다. 산업부에 따르면 2008년부터 2025년까지 누적 603개 기업이 1367억 원의 융자 지원과 컨설팅을 받았다. 산업부는 이번 지원대상 확대와 함께 앞으로도 기업 지원을 더 늘려 나갈 계획이라고 밝혔다.</p>', '개정 통상변화대응법이 22일 시행됐다. 외국의 통상조치로 피해를 본 기업도 지원 대상이 되고 판로 개척 지원이 새로 추가된 점을 대상, 지원 방식, 시행 시기, 신청 창구 순으로 정리했다.', '/sites/newstoday/photos/ntd-feature-special-1.webp', '2026-10-22T07:21:00+09:00'::timestamptz, array['통상변화대응법','산업통상부','수출기업','판로개척','정책해설']::text[], 'in_review'),
  ('feature-special', '비대면진료 초진·처방 기준, 12월 24일 시행 앞두고 무엇이 달라지나', '<p>@@BYLINE@@&nbsp;보건복지부는 오는 12월 24일 시행되는 개정 ‘의료법’에 맞춰 비대면진료의 대상환자와 처방 기준, 의료기관의 진료 기준, 중개매체 신고·인증 기준 등을 정한 ‘의료법 시행규칙’과 ‘의료관계 행정처분 규칙’ 일부개정령안을 10월 19일부터 11월 9일까지 입법예고한다고 밝혔다. 정책브리핑 정책뉴스에 따르면 9월 23일부터 11월 2일까지 입법예고 중인 ‘의료법 시행령’ 개정안의 주요 내용도 함께 안내됐다. 아래 내용은 모두 입법예고 단계의 개정안이다.</p><p>누가 받을 수 있는지부터 보면, 일반 비대면진료는 해당 의료기관에서 6개월 이내 같은 증상으로 대면진료를 받은 환자가 대상이다. 이 이력이 없어도 주민등록상 주소지와 의료기관 소재지가 같은 시·도에 있으면 초진 비대면진료가 가능하다. 비대면진료지원시스템에 실거주지를 등록한 환자는 실거주지가 기준이다. 희귀질환자, 제1형 당뇨병 환자, 등록장애인, 장기요양수급자 등 법령에서 정한 환자는 다른 시·도 의료기관에서도 초진을 받을 수 있다.</p><img src="/sites/newstoday/photos/ntd-feature-special-2.webp" alt="화상으로 환자를 진료하는 원격의료 시스템(멕시코 병원 촬영, 자료사진). 한국 현장 사진이 아니다. ⓒ Intel Free Press / 위키미디어 공용 (CC BY-SA 2.0)"><p><em>▲ 화상으로 환자를 진료하는 원격의료 시스템(멕시코 병원 촬영, 자료사진). 한국 현장 사진이 아니다. ⓒ Intel Free Press / 위키미디어 공용 (CC BY-SA 2.0)</em></p><p>의료기관 기준도 구체화됐다. 비대면진료는 의원급 의료기관에서 하는 것이 원칙이고, 희귀질환자나 수술·시술 후 경과관찰이 필요한 환자 등 불가피한 경우에는 정해진 기준에 따라 병원급에서도 할 수 있다. 의료기관의 비대면진료 건수는 반기별 전체 진료 건수의 30% 이내로 제한되고, 의료인별 반기 월평균 건수는 의사 500건, 치과의사·한의사 130건 이내다. 야간·휴일 진료 등은 건수 산정에서 제외한다.</p><p>처방 기준을 보면, 초진 비대면진료의 의약품 처방일수는 원칙적으로 7일 이내다. 해당 질환의 진료·처방 이력이 확인되고 의료인이 기존 치료를 계속할 필요가 있다고 판단하면 한 차례에 한해 30일 이내로 처방할 수 있다. 마약·향정신성의약품, 오·남용 우려 의약품, 비만치료제는 원칙적으로 처방이 금지되며, 희귀질환자 등의 치료에 필요한 경우 일정한 요건을 갖춰 마약·향정신성의약품을 예외적으로 처방할 수 있다.</p><p>진료 방식과 약 전달 방식도 정해진다. 의료인은 비대면진료 전에 환자 본인 여부와 대상환자 요건을 확인해야 하며, 진료는 화상통신이 원칙이고 일정한 경우 음성통신을 허용한다. 조제의약품을 약국 밖에서 인도할 수 있는 지역과 인도 업무의 위탁 근거가 마련되고, 복약지도와 배송업자의 배송 약관 마련 등 인도 과정의 준수사항도 정해진다. 의약품 무상 제공 등 환자 유인행위와 배송업자의 부당한 금품 제공은 금지된다.</p><p>비대면진료 중개매체를 운영하려는 자는 매체 명칭과 운영방식, 이용료, 정보 안전성 확보 조치 등을 신고해야 한다. 누적 가입자 수가 10만 명 이상인 중개매체 운영자는 의무적으로 인증을 신청해야 한다. 시행령 개정안에는 위기경보가 심각 단계로 발령되는 등 대면진료 제공이 현저히 곤란한 경우 비대면진료 기준을 한시적으로 완화할 수 있는 요건과 절차도 담겼다.</p><p>의견 제출은 시행규칙과 행정처분 규칙 개정안은 11월 9일까지, 시행령 개정안은 11월 2일까지다. 복지부 의료정보정책과(의약품 인도 관련은 약무정책과) 또는 국민참여입법센터를 이용할 수 있다. 복지부는 입법예고 기간에 국민과 관계기관의 의견을 수렴한 뒤 개정안을 확정할 예정이라고 밝혔다.</p>', '보건복지부가 12월 24일 시행되는 개정 의료법에 맞춰 비대면진료 대상 환자와 처방 기준 등을 담은 시행규칙 개정안을 입법예고했다. 대상 환자, 처방일수, 의견 제출 방법을 정리했다.', '/sites/newstoday/photos/ntd-feature-special-2.webp', '2026-10-19T15:30:00+09:00'::timestamptz, array['비대면진료','의료법','보건복지부','입법예고','정책해설']::text[], 'in_review'),
  ('feature-special', '행정서비스 1658개 제출서류 간소화, 신청할 때 무엇이 달라지나', '<p>@@BYLINE@@&nbsp;행정안전부는 19일 행정서비스 1658개의 제출서류 간소화를 완료했다고 밝혔다. 정책브리핑 정책뉴스에 따르면 국민이 행정정보 확인에 동의하면 필요한 서류를 직접 발급받아 제출하지 않고도 서비스를 신청할 수 있게 됐다.</p><p>무엇이 달라지는지는 신청 방식이다. 중앙부처와 지방정부의 해당 행정서비스에서는 신청인이 서류를 일일이 떼어 내는 대신 행정정보 확인에 동의하면 된다. 행안부는 2024년부터 누적 1억 건 이상의 정보 조회를 통해 서류 제출을 줄이고 사회적·경제적 비용을 절감했다고 설명했다. 언제 간소화됐는지도 나뉜다. 간소화한 서비스는 2024년 421개, 2025년 679개, 올해 3분기 558개로 모두 1658개다.</p><img src="/sites/newstoday/photos/ntd-feature-special-3.webp" alt="정부세종청사 정문 일대(2019년 6월 촬영, 자료사진). 기사 속 행정서비스 전반을 상징하는 사진이다. ⓒ *Youngjin / 위키미디어 공용 (CC BY-SA 3.0)"><p><em>▲ 정부세종청사 정문 일대(2019년 6월 촬영, 자료사진). 기사 속 행정서비스 전반을 상징하는 사진이다. ⓒ *Youngjin / 위키미디어 공용 (CC BY-SA 3.0)</em></p><p>누가 혜택을 보는지는 분야별 분포에서 가늠할 수 있다. 소상공인·사업자 서비스가 535개(32.3%)로 가장 많았다. 장애인·노인·취약계층·보훈 서비스 204개(12.3%), 생활·세금·요금감면 193개(11.6%), 학생·청년·교육훈련 124개(7.5%), 신혼·임신·출산·육아·다자녀 107개(6.5%)가 뒤를 이었다.</p><p>자격확인 86개(5.2%), 근로자 84개(5.1%), 농어민 67개(4.0%), 기타 258개(15.6%)도 간소화 대상에 포함됐다. 처리기관별로는 시·군·구 등 지방정부 서비스가 전체 간소화 서비스의 55.6%를 차지했다.</p><p>행안부는 행정정보 공동이용 대상 정보를 2025년 174종에서 2026년 181종으로 늘렸다. 여러 지방정부가 공통으로 처리하는 행정서비스 143종을 표준화해 담당 공무원의 정보 확인도 지원했다고 밝혔다.</p><p>행안부는 행정정보 공동이용 대상 정보를 계속 발굴해 제출서류 간소화를 확대할 계획이다. 윤호중 행정안전부 장관은 “앞으로도 보다 쉽고 편리한 행정서비스를 위해 서류 간소화를 지속적으로 확대하고, 국민이 체감하는 진정한 ''원스톱 행정서비스'' 구현을 위해 노력하겠다”고 밝혔다.</p>', '행정안전부가 행정서비스 1658개의 제출서류 간소화를 마쳤다고 19일 밝혔다. 행정정보 확인에 동의하면 서류를 직접 발급해 내지 않아도 신청할 수 있다. 연도별 현황과 분야별 분포를 정리했다.', '/sites/newstoday/photos/ntd-feature-special-3.webp', '2026-10-19T11:40:00+09:00'::timestamptz, array['행정안전부','서류 간소화','행정서비스','행정정보 공동이용','정책해설']::text[], 'in_review'),
  ('feature-special', '수능 당일 지원대책, 출근 시간·차량 통제 무엇이 달라지나', '<p>@@BYLINE@@&nbsp;교육부는 20일 국무회의에서 ‘2027학년도 대학수학능력시험(수능) 당일 안정적 시험 시행을 위한 지원대책’을 보고했다고 보도자료에서 밝혔다. 올해 수능은 11월 19일(목) 오전 8시 40분부터 오후 5시 45분(일반수험생 기준)까지 전국 85개 시험지구 1312개 시험장에서 치러진다. 응시 예정자는 551,864명으로 전년보다 2,310명 줄었다.</p><p>출근 시간과 대중교통부터 달라진다. 교육부는 수능 당일 아침 수험생이 교통 혼잡으로 늦지 않도록 관공서·기업체 등에 출근 시간을 오전 10시 이후로 조정해 달라고 협조를 요청한다. 수험생 등교 시간대(오전 6시~8시 10분)에는 수도권 지하철 운행 대수를 늘리고, 경찰서 등 행정기관의 비상 수송차량을 수험생 이동 경로에 배치한다.</p><img src="/sites/newstoday/photos/ntd-feature-special-4.webp" alt="수능 시험장으로 쓰인 교실의 모습(2017년 11월 촬영, 자료사진). ⓒ 고려 / 위키미디어 공용 (CC BY 4.0)"><p><em>▲ 수능 시험장으로 쓰인 교실의 모습(2017년 11월 촬영, 자료사진). ⓒ 고려 / 위키미디어 공용 (CC BY 4.0)</em></p><p>시험장 주변 차량 통제도 있다. 시험장 주변 교통 혼잡을 막기 위해 수능 당일 시험장 200m 전방부터 차량 출입을 통제한다. 교육부는 이에 따라 자가용을 이용하는 수험생은 시험장 200m 전방에서 내려 걸어가야 한다고 안내했다.</p><p>소음 관리 대책은 영어영역 듣기평가에 맞춰진다. 3교시 듣기평가 시간(13시 10분~13시 35분, 25분간)에 소음이 생기지 않도록 항공기·헬리콥터 이착륙 시간을 조정하고, 포 사격과 전차 이동 등 군사훈련을 잠시 중단한다. 듣기평가 시간대 외에도 시험장 주변을 지나는 버스·열차는 서행하며 경적 사용을 자제하고, 시험장 주변 행사장·공사장의 생활소음도 최대한 자제해 달라고 당부했다.</p><p>기상 악화와 자연재해 대비책도 마련됐다. 수험생은 11월 13일(금)부터 기상청 누리집(www.weather.go.kr)에서 시험장 날씨 정보를 미리 확인할 수 있다. 시·도는 도서·벽지 수험생 수송 대책과 제설 대책을 마련하고, 16개 시·도교육청은 전체 시험장을 안전 점검하며 지진 발생에 대비한 정보 전달 체계를 구축한다.</p><p>문답지 보안 관리도 강화된다. 교육부는 경찰청, 시·도교육청과 함께 철저한 경비 체계를 마련하고 모든 시험지구에 교육부 중앙협력관을 파견해 문답지 관리를 지원한다. 시험편의제공대상자(중증시각장애)를 포함한 시험 종료 시각은 21시 48분이다.</p><p>최교진 교육부 장관은 “수험생 여러분이 그동안 갈고닦은 실력을 충분히 발휘할 수 있도록 모든 부처가 힘을 모아 최선을 다해 돕겠다”고 말했다. 교육부는 수험생 유의사항은 추후 별도로 안내할 예정이라고 밝혔다.</p>', '교육부가 20일 국무회의에 보고한 수능 당일 지원대책을 정리했다. 11월 19일 전국 1312개 시험장에서 55만여 명이 응시하며 출근 시간 조정, 시험장 200m 앞 차량 통제 등이 시행된다.', '/sites/newstoday/photos/ntd-feature-special-4.webp', '2026-10-20T13:15:00+09:00'::timestamptz, array['수능','대학수학능력시험','교육부','수험생','정책해설']::text[], 'in_review'),
  ('feature-special', '학부모 지원·학교 민원 대응, 초·중등교육법 시행령 무엇이 달라지나', '<p>@@BYLINE@@&nbsp;교육부는 20일 국무회의에서 ‘초·중등교육법 시행령’ 일부개정령안이 심의·의결됐다고 밝혔다. 교육부 보도자료에 따르면 이번 개정은 지난 4월 개정된 초·중등교육법이 10월 29일 시행되는 데 따른 후속 조치다.</p><p>먼저 보호자 지원 시책이다. 교육부 장관과 교육감은 2027년부터 보호자 지원 시책을 매년 수립·시행한다. 시책에는 보호자 지원을 위한 교육·상담 및 정보 제공, 학교와 학부모지원센터 간 협력체계 구축·운영, 전문인력 양성 등을 담도록 했다. 현장 수요를 반영하도록 학교와 보호자 등의 의견을 수렴하고, 보호자 지원 사업과 인력·예산 현황 등에 대한 실태조사를 할 근거도 마련했다.</p><img src="/sites/newstoday/photos/ntd-feature-special-5.webp" alt="초등학교 교사 건물(2008년 촬영, 자료사진). 기사와 직접 관련된 학교가 아니다. ⓒ InSapphoWeTrust / 위키미디어 공용 (CC BY-SA 2.0)"><p><em>▲ 초등학교 교사 건물(2008년 촬영, 자료사진). 기사와 직접 관련된 학교가 아니다. ⓒ InSapphoWeTrust / 위키미디어 공용 (CC BY-SA 2.0)</em></p><p>학부모지원센터의 역할도 구체화됐다. 전국학부모지원센터는 법에서 정한 업무 외에 보호자 지원 관련 조사·연구와 전문인력 연수 과정의 개발·운영을 맡는다. 지역학부모지원센터는 보호자 교육·상담 프로그램 운영, 보호자 지원 관련 제도 안내, 보호자의 교육정책 이해와 보호자·학교·교육행정기관 간 소통 지원 등을 수행한다. 센터로 지정받으려는 기관·단체는 적정한 조직·인력과 시설, 사업 계획과 운영 규정 등을 갖춰야 한다.</p><p>학교 민원 대응 절차도 규정됐다. 교육활동을 침해할 우려가 있는 학교 민원에 대해 학교장은 민원 제기자에게 이 사실을 알리고 행위의 중지를 요청해야 한다. 중지 요청에 따르지 않는 경우 학교장은 전화나 면담의 종료, 퇴거 또는 일시적 출입 제한, 수사기관 신고 등 필요한 조치를 할 수 있다.</p><p>언제부터인지도 정리된다. 학교의 민원대응팀과 관할청의 학교민원대응지원팀을 법제화하는 개정 초·중등교육법이 10월 29일 시행된다. 교육부는 이번 시행령 개정과 함께 기관 단위의 학교민원 대응 체계가 현장에 자리 잡을 것으로 기대했다. 보호자 지원과 관련해서는 국가와 지방자치단체의 지원이 보다 내실 있게 이뤄질 것으로 기대된다고 밝혔다.</p><p>최교진 교육부 장관은 “이번 개정으로 자녀 교육 및 학교 협력 등에 대한 학부모의 역량 함양을 지원하는 한편, 교원이 교육활동에 전념할 수 있는 제도적 기반을 마련하였다”고 말했다. 교육부는 교육청 및 학부모지원센터와 함께 개정안에 따른 보호자 지원 시책 수립과 시행 등을 체계적으로 추진하겠다고 밝혔다.</p>', '개정 초·중등교육법이 10월 29일 시행되는 데 따른 시행령 개정안이 20일 국무회의를 통과했다. 보호자 지원 시책과 학부모지원센터 역할, 학교 민원 대응 절차가 시행령에 구체적으로 담겼다.', '/sites/newstoday/photos/ntd-feature-special-5.webp', '2026-10-20T16:05:00+09:00'::timestamptz, array['초중등교육법','학부모지원센터','학교민원','교육부','정책해설']::text[], 'in_review'),
  ('photo', '동구릉 건원릉 능침, 11월 3~8일 억새 절정기 특별 개방', '<p>@@BYLINE@@&nbsp;국가유산청 궁능유적본부 조선왕릉동부지구관리소는 19일 보도자료에서 오는 11월 3일부터 8일까지 6일간 경기 구리시 동구릉에 있는 건원릉 능침을 특별 개방한다고 밝혔다. 매일 오전 10시와 오후 2시 두 차례 운영하며, 회차별 관람 시간은 한 시간이다.</p><p>건원릉은 조선을 건국한 태조 이성계의 능으로, 조선왕릉 가운데 유일하게 봉분이 억새로 덮여 있다. 국가유산청은 태조의 유언에 따라 고향인 함흥의 억새를 옮겨와 봉분을 조성했기 때문이라고 전해진다고 설명했다. 능침은 왕릉의 주인이 묻혀 있는 곳을 뜻한다.</p><img src="/sites/newstoday/photos/ntd-photo-1.webp" alt="경기 구리 동구릉 건원릉 능침의 봉분과 석물. 봉분이 억새로 덮여 있다. 2005년 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)"><p><em>▲ 경기 구리 동구릉 건원릉 능침의 봉분과 석물. 봉분이 억새로 덮여 있다. 2005년 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)</em></p><p>관람객은 해설사의 이야기를 들으며 평소 쉽게 접하기 어려운 건원릉 능침을 둘러볼 수 있다. 특별 개방은 무료이며 동구릉 입장료와 주차요금은 별도다. 참가 신청은 10월 20일 오전 10시부터 궁능유적본부 누리집 통합예약에서 회차당 20명씩 선착순으로 받고, 당일 현장 접수(회차당 10명)도 가능하다.</p><p>국가유산청은 억새 절정기를 맞아 마련한 이번 특별 개방을 비롯해, 앞으로도 국내외 관람객이 조선왕릉의 가치를 새롭게 발견할 수 있는 다양한 프로그램을 선보일 예정이라고 밝혔다.</p>', '국가유산청 궁능유적본부 조선왕릉동부지구관리소가 11월 3일부터 8일까지 경기 구리 동구릉 건원릉 능침을 매일 두 차례 특별 개방한다. 봉분이 억새로 덮인 태조 이성계의 능이다. 사전 신청은 궁능유적본부 누리집에서 받는다.', '/sites/newstoday/photos/ntd-photo-1.webp', '2026-10-19T09:41:00+09:00'::timestamptz, array['건원릉','동구릉','국가유산청','조선왕릉','억새']::text[], 'in_review'),
  ('photo', '명승 백악산 남서자락 탐방로 1.32㎞, 17일 추가 개방', '<p>@@BYLINE@@&nbsp;국가유산청은 14일 보도자료에서 명승 ''서울 백악산 일원''의 남서자락 탐방로 1.32㎞를 10월 17일 오전 9시부터 국민에게 개방한다고 밝혔다. 이에 앞서 16일 오후 3시 30분 백악산 한양도성 창의문 일원에서 3단계 전면 개방 기념행사를 연다.</p><p>1968년 1·21사태 이후 출입이 제한됐던 백악산은 2020년 1단계(북측 한양도성 탐방길 2.2㎞)와 2022년 2단계(남동자락 숲 일대 3.0㎞)로 나눠 개방돼 왔다. 이번 3단계로 마지막 남은 남서자락이 열리면서 주요 탐방로가 하나로 연결된다고 국가유산청은 설명했다.</p><img src="/sites/newstoday/photos/ntd-photo-2.webp" alt="백악산 한양도성 창의문. 3단계 전면 개방 기념행사가 열리는 장소로, 2009년 4월 촬영한 자료사진이다. ⓒ Shiwon Cho (CC BY-SA 2.0, 위키미디어 공용)"><p><em>▲ 백악산 한양도성 창의문. 3단계 전면 개방 기념행사가 열리는 장소로, 2009년 4월 촬영한 자료사진이다. ⓒ Shiwon Cho (CC BY-SA 2.0, 위키미디어 공용)</em></p><p>새로 열리는 구간은 창의문에서 정상으로 향하는 길의 첫 쉼터인 ''돌고래쉼터''에서 시작해 약수터 ''만세동방'', ''1·21사태소나무''를 잇는다. 인왕산과 남산, 청와대, 경복궁 등이 내려다보이는 길로, 조망 쉼터 4곳도 새로 조성했다. 24시간 운영하며 지정 탐방로를 이용해야 하고 이용료는 없다.</p><p>이번 개방은 국가유산청과 대통령경호처, 서울특별시, 종로구, 국가유산진흥원이 협력해 추진했다. 국가유산청은 앞으로 한양도성·경복궁·청와대 등 주변 역사문화자원과 연계한 탐방·해설·활용 프로그램을 확대해 나갈 계획이라고 밝혔다.</p>', '국가유산청이 명승 백악산 남서자락 탐방로 1.32㎞를 10월 17일 오전 9시부터 추가 개방한다. 3단계에 걸친 개방이 마무리돼 주요 탐방로가 하나로 이어진다. 16일에는 창의문 일원에서 기념행사가 열린다.', '/sites/newstoday/photos/ntd-photo-2.webp', '2026-10-14T10:23:00+09:00'::timestamptz, array['백악산','북악산','국가유산청','한양도성','탐방로']::text[], 'in_review'),
  ('photo', '경복궁 장고에서 ''장 담그기'' 체험, 11월 4~8일 열려', '<p>@@BYLINE@@&nbsp;국가유산청 궁능유적본부는 20일 보도자료에서 국가유산진흥원과 함께 오는 11월 4일부터 8일까지 서울 종로구 경복궁에서 ''한국의 장 담그기 문화''를 주제로 2026년 「궁궐 일상모습 재현 및 체험」 행사를 연다고 밝혔다.</p><p>행사는 평소 개방하지 않는 경복궁 장고를 열어 궁중의 음식 문화를 재현하고, 2024년 유네스코 인류무형유산에 오른 ''한국의 장 담그기 문화''를 알리기 위해 마련됐다. 장고는 경복궁에서 궁중 장독을 관리하고 보관하던 곳이다. 행사 기간 장고 일원에서는 전시와 포토존, 소규모 체험극 같은 현장 이벤트가 열리며, 경복궁 관람객이면 누구나 무료로 즐길 수 있다.</p><img src="/sites/newstoday/photos/ntd-photo-3.webp" alt="경복궁 장고 일원에 층층이 놓인 장독들. 이번 행사가 열리는 장소로, 2012년 9월 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)"><p><em>▲ 경복궁 장고 일원에 층층이 놓인 장독들. 이번 행사가 열리는 장소로, 2012년 9월 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)</em></p><p>11월 6일부터 8일까지 진행하는 ''장 담그기'' 체험에서는 대한민국 식품명인(전통장) 기순도 명인에게 장에 대한 이론 교육을 듣고 직접 장을 담근다. 하루 4회, 회당 2인 1조 10팀(20명)이 참여한다. 참가자가 담근 장은 경복궁 장고에서 약 4개월간 숙성한 뒤 2027년 봄(3월 5~7일 예정) ''장 가르기'' 체험을 거쳐 된장과 간장으로 가져갈 수 있다.</p><p>체험 사전예매는 10월 21일 오후 2시부터 티켓링크에서 선착순으로 진행한다. 참가비는 1매당 5만 원이며 1매로 2명이 체험할 수 있다. 자세한 내용은 궁능유적본부와 국가유산진흥원 누리집에서 확인할 수 있다.</p>', '국가유산청 궁능유적본부가 11월 4일부터 8일까지 경복궁 장고 일원에서 한국의 장 담그기 문화를 소개하는 행사를 연다. 6~8일에는 장 담그기 체험이 마련된다. 체험은 사전 예매로 운영한다.', '/sites/newstoday/photos/ntd-photo-3.webp', '2026-10-20T11:07:00+09:00'::timestamptz, array['경복궁','장고','장 담그기','국가유산청','궁궐체험']::text[], 'in_review'),
  ('photo', '창경궁·창덕궁 야간 탐방 ''동궐동락'', 11월 10~15일 열려', '<p>@@BYLINE@@&nbsp;국가유산청 궁능유적본부는 21일 보도자료에서 국가유산진흥원과 함께 오는 11월 10일부터 15일까지 6일간 2026년 「동궐동락」 행사를 개최한다고 밝혔다. 동궐은 조선시대 창덕궁과 창경궁을 함께 이르던 이름으로, 이 행사는 두 궁궐에서 진행하는 야간 탐방 프로그램이다. 행사 기간에는 창경궁 상시 야간관람을 운영하지 않는다.</p><p>참가자는 도화서 화원의 해설과 함께 창경궁 홍화문에서 출발해 옥천교, 명정전, 통명전, 창덕궁 의두합, 애련지, 부용지, 창경궁 대온실, 대춘당지를 거쳐 홍화문으로 돌아오는 길을 걷는다. 이 가운데 명정전, 통명전, 의두합, 대춘당지 4곳에서는 장소와 관련된 인물의 일화를 다룬 소규모 극을 볼 수 있다.</p><img src="/sites/newstoday/photos/ntd-photo-5.webp" alt="단풍이 물든 창경궁 대온실 전경. 동궐동락 탐방 경로에 포함된 장소로, 2012년 11월 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)"><p><em>▲ 단풍이 물든 창경궁 대온실 전경. 동궐동락 탐방 경로에 포함된 장소로, 2012년 11월 촬영한 자료사진이다. ⓒ 문화재청 (공공누리 제1유형, 위키미디어 공용)</em></p><p>자유 관람 시간에는 평소 개방하지 않던 영춘문을 지나 창덕궁과 창경궁 후원을 오갈 수 있다. 영화당에서는 국악 공연이 열리고, 후원 곳곳에서 왕실의 일상을 재현하는 배우들과 사진을 남길 수 있다. 행사는 하루 4회(오후 6시, 6시 30분, 7시, 7시 30분) 110분씩 운영한다.</p><p>올해는 관람 기회의 공정성을 높이기 위해 추첨제로 참가자를 모집한다. 응모는 10월 22일 오후 2시부터 티켓링크에서 받으며, 만 65세 이상과 장애인, 국가보훈등록증 소지자는 11월 5일부터 티켓링크 전화상담실로도 예매할 수 있다. 참가비는 1인 4만 원이고 1인 최대 2매까지 예매할 수 있다.</p>', '국가유산청 궁능유적본부가 11월 10일부터 15일까지 창덕궁과 창경궁에서 야간 몰입형 탐방 프로그램 동궐동락을 연다. 올해는 예매 방식에 추첨제를 도입했다. 응모는 10월 22일부터 받는다.', '/sites/newstoday/photos/ntd-photo-5.webp', '2026-10-21T13:18:00+09:00'::timestamptz, array['동궐동락','창경궁','창덕궁','국가유산청','야간관람']::text[], 'in_review')
) as v(slug, title, body, excerpt, thumb, published_at, tags, status)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where ctx.author_id is not null
  and not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 기자명 '편집국', 기자 이메일 비우기, AI 메모(확인할 점·원문 주소·사진 이용 조건)
--   (기자 이메일은 DB 규칙이 대표 이메일로 채우므로, 잠깐 그 규칙을 끄고 비운 뒤 다시 켠다)
do $fix$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '편집국'
    from outlets o, (values
      ('AI가 폐기물 식별·배출 안내…서울 은평구서 ''가져가'' 앱 실증 시작'),
      ('AI 학습용 데이터 연계 의무화…AI기본법·데이터산업법 개정안 국무회의 통과'),
      ('과기정통부·세계은행, 서울서 국제 AI·디지털 정상회의…60여 개국 참석'),
      ('과기정통부, 13~14일 코엑스서 ''피지컬 AI Tech Week'' 개최'),
      ('KAIST·UNIST 등, 2차원 반도체 결정 생성 위치 제어…네이처 게재'),
      ('IBS, 원자 치환으로 한 박막에 반도체·절연체·준금속 구현…사이언스 게재'),
      ('인천 지하철 1·2호선 와이파이 5G로 고도화…과기정통부, 현장 체험 행사'),
      ('9월 ICT 수출 751.5억 달러 역대 최고…반도체 603.3억 달러로 견인'),
      ('과기정통부, 개방형 양자 테스트베드 3개 거점으로 확대…올해 74억 원 투입'),
      ('정보보호 공시 의무, 2027년부터 전체 상장사로 확대…시행령 개정안 의결'),
      ('건강검진 대상 아니어도 국가 통합 바이오 빅데이터 사업 참여 가능'),
      ('행안부, 행정서비스 1,658개 제출서류 간소화 완료'),
      ('해수부, 표층수온·해수면 높이 3개월 전망 해설서 시범 제공'),
      ('올해 쌀 예상생산량 351만 8천 톤, 전년보다 0.6% 감소 전망'),
      ('해수부, AI·공공데이터 활용 어업 현장 서비스 3종 선보여'),
      ('한-EU 에너지·환경·기후변화 작업반 회의, 그린 파트너십 논의'),
      ('한-싱가포르, 제1차 공동운영위원회 열고 협력 방안 논의'),
      ('정부, CEPI·Unitaid와 2,800만 달러 규모 기여약정서 체결'),
      ('외교부·기후에너지환경부, 카자흐스탄에 물산업 협력사절단 파견'),
